NAME = 'Tausug: Tausug Kitab Injil'
BOOK = 'Hebrews'

CHAPTERS = {
    1: {
        1: "Manjari, sin masa nakauna yadtu, nakamataud in Tuhan nagparman pa manga kaapu'-apuan natu' naug dayn ha manga nabi, lāgi' mataud in ginisan sin dān pagpasampay sin Parman niya.",
        2: "Sagawa' ha masa bihaun, amu in tagnaan na sin kahinapusan sin masa natu', in nagpasampay sin Parman sin Tuhan mari kātu'niyu, amuna in Anak Tuhan. Siya da isab in nagpapanjari sin katilingkal ālam iban sin katān luun niya dayn ha kabayaan sin Tuhan. Lāgi' in unu-unu katān ha katilingkal ālam asal kiyapusaka' kaniya sin Tuhan.",
        3: "Duun kaniya kakitaan in sahaya iban sipat sin Tuhan, karna' in siya iban Tuhan magsibu' tuud. Siya da isab in tagkaputan sin katilingkal ālam, iban dayn ha sabab sin kusug sin kawasa sin Parman kapagbayaan niya in unu-unu katān ha katilingkal ālam. Iban pag'ubus niya mayan hīnang in dān sin hikaampun sin manga dusa sin mānusiya', nagbalik na siya pa surga', ampa siya limingkud ha dapit pa tuu sin Tuhan amu in sangat-kawasa, karna' kiyabugsu' na kaniya sin Tuhan in kawasa magbaya' ha unu-unu katān.",
        4: 'Na, labi tuud makawasa in Anak Tuhan dayn ha manga malāikat, sabab minsan sadja in gulalan kaniya sin Tuhan labi mataas dayn ha gulalan ha manga malāikat.',
        5: "Karna' wala' in Tuhan nakapagparman pa manga malāikat niya sin biya' ha ini amu agi, “In ikaw Anak ku. Iban bihaun aku na in Ama' mu.” Damikkiyan wala' da isab in Tuhan nakapagparman sin pasal ini ha tungud sin hisiyu-siyu na malāikat, amu agi, “In aku Ama' mu, iban in ikaw Anak ku.” Sagawa' in Tuhan nagparman ha yan pa amu in Anak niya.",
        6: "Lāgi' maray' mayan palahilun sin Tuhan pa dunya in Anak niya amu in sangat-kawasa nagparman siya pa manga malāikat, amu agi, “In kamu katān manga malāikat ku subay sumumba kaniya.”",
        7: "Sagawa' ha pasal sin manga malāikat, biya' ha ini in Parman sin Tuhan, amu agi, “In manga malāikat daraakun ku sadja, miyamagad sadja sin daakan ku biya' sin hangin iban kāyu.”",
        8: "Samantara' ha pasal sin amu in Anak niya, ini in kiyaparman sin Tuhan, amu agi, “In pagsultan mu, ū Tuhan, tumatas kasaumulan. Mabuntul tuud in pamarinta mu ha manga tau.",
        9: "In kabayaan mu in unu-unu mabuntul, iban marugal kaw ha unu-unu mangī'. Na, hangkan dīhilan kaw sin Tuhan mu kakuyagan iban kalagguan, amu in labi tuud dayn sin dīhil niya ha manga panāiban mu.”",
        10: "Nagparman pa isab in Tuhan pa amu in Anak niya, amu agi, “Ikaw, Panghu', in nagpapanjari sin dunya iban sin katilingkal ālam dayn ha panagnaan. Ikaw da in naghinang, way dugaing.",
        11: "In dunya iban ālam ha susūngun malanyap da, sagawa' in ikaw di' mapinda kasaumulan. Biya' da sila sin tamungun dumaan, di' na kalagihan.",
        12: "Hibugit mu na in manga yan biya' sapantun tamungun daan, ampa mu gantian sin ba'gu. Sagawa' in ikaw di' magkapinda, iban wayruun kahinapusan sin kabuhi' mu.”",
        13: "In Tuhan wala' tuud nakapagparman pa hisiyu-siyu na malāikat biya' sin kiyaparman niya ha amu in Anak niya, amu agi, “Lingkud kaw dī ha dapit pa tuu ku sampay ku daugun in katān kimukuntara kaymu. Mahinang sila biya' paggigiikan sin siki mu.”",
        14: "Na, pagga biya' ha yan, unu in manga malāikat? Na, in manga malāikat, daraakun sadja sin Tuhan. Di' sila kakitaan, sagawa' sila in naraak sin Tuhan tumabang ha manga tau katān amu in makatayma' sin kalappasan dayn ha Tuhan.",
    },
    2: {
        1: "Na, pagga bihādtu in kusug sin kawasa sin Almasi, na subay taniyu pahugutun tuud in pagkahagad natu' sin bayta' kasabunnalan diyungug natu' pasal sin Almasi ha supaya kitaniyu di' marā simiha' pa dugaing.",
        2: "Karna' in sara', amu in bayta' piyasampay sin manga malāikat pa manga kamaasan natu' sin timpu nakauna yadtu, mattan tuud bunnal, sabab hisiyu-siyu in wala' miyagad atawa nagkahagad, piyaratungan sila kasiksaan tūp ha nahinang nila mangī'.",
        3: "Na, hangkan biya' diin in kapaguy natu' dayn ha kasiksaan bang taniyu pasāran na in kalappasan dakula'? Baran tuud sin Panghu' Īsa in tagna' nagpamahalayak sin pasal kalappasan. Pag'ubus in manga nakarungug kaniya amu isab in nagpaingat iban nagpakita' kātu'niyu sin kasabunnalan sin bayta' niya.",
        4: "Damikkiyan, in Tuhan simaksi' da isab sin bunnal in bayta' yan, sabab in manga tau nagpamahalayak sin bayta' yan, dīhilan niya barakat huminang sin manga hinang makainu-inu iban mu'jijat ginis-ginisan, amu in tanda' sin kasabunnalan. Iban dayn ha kahandak niya piyatulunan niya sila sin Rū niya, amu in dimihil ingat iban kusug kanila.",
        5: "Biya' na sin nasabbut ku kaniyu, bang ba'guhun na sin Tuhan in dunya ini biya' sin iyampa piyapanjari, na mānusiya' in dihilan sin Tuhan kawasa makapagbaya' ha lawm sin dunya yan, bukun manga malāikat.",
        6: "Karna' kiyasulat ha lawm Kitab, amu agi, “Ū Tuhan, mayta' baha' piyaparuli mu tuud in mānusiya', iban malabi tuud sila ha lawm atay mu, malayngkan, in sila mānusiya' sadja?",
        7: "In tagna' piyapanjari mu in mānusiya' mababa' dayn ha manga malāikat, sagawa' hangkaray' da. Ubus ampa mu sila dīhilan kasanglitan iban kalagguan.",
        8: "Lāgi' mānusiya' in dihilan mu kapatutan magbaya' ha unu-unu katān.” Na, amu yan in kiyabayta' ha Kitab sin in mānusiya' dihilan sin Tuhan kapatutan magbaya' ha unu-unu katān. Wayruun in di' niya kapagbayaan. Sagawa' ha bihaun di' natu' pa kakitaan in mānusiya' makapagbaya' ha unu-unu katān.",
        9: "Malayngkan, minsan biya' ha yan, in bayta' yan timagna' na nagmakbul duun kan Īsa. Karna' limahil mayan hi Īsa pa dunya miyaba' siya hangkaray' dayn ha manga malāikat, ha supaya dayn ha sabab sin lasa sin Tuhan ha mānusiya', in siya subay lumabay kabinsanaan iban mapatay ha pasalan sin mānusiya' katān. Na, bihaun kaingatan natu' kiyarihilan na siya sin Tuhan kasanglitan iban kalagguan, sabab sin kamatay liyabayan niya.",
        10: "Mapatut tuud in hīnang sin Tuhan, amu in nagpapanjari iban makapagbaya' ha unu-unu katān, sin piyalabay niya kabinsanaan hi Īsa, ha supaya magmakbul na tuud in kiyamaksud sin Tuhan kaniya manglappas ha manga mānusiya'. Karna' dayn ha sabab sin hinang hi Īsa, mataud mānusiya' in mahinang anak sin Tuhan iban makasāw sin kasanglitan iban kalagguan niya, karna' hi Īsa in dumā kanila pa kalappasan.",
        11: "Lāgi' suchihun hi Īsa in manga mānusiya' dayn ha manga dusa nila. Na, in manga tau masuchi niya maghangka-Ama' na iban siya. Hangkan di' hi Īsa masipug umiyan sin in sila taymanghud niya.",
        12: "Biya' na sin agi hi Īsa ha Tuhan ha lawm Kitab, laung niya, “Baytaan ku in manga taymanghud ku sin pasal nahinang mu, iban pudjihun ta kaw duun ha pagtipunan nila.”",
        13: "Iban pagga hi Īsa mānusiya' biya' kātu'niyu, imiyan siya, laung niya, “In aku mangandul tuud ha Tuhan.” Iban laung niya pa isab, “Yari aku iban sin pagkahi ku anak sin Tuhan, amu in piyangandul niya kāku'.”",
        14: "Na, pagga in manga piyag'iyan hi Īsa anak sin Tuhan, manga mānusiya' da, amu in magkamatay, na nagbaran mānusiya' hi Īsa, ha supaya in kajarihanan niya mabiya' da tuud sin manga mānusiya'. Hīnang niya in biya' ha yan ha supaya siya makalabay kamatay, karna' dayn ha sabab sin kamatay niya daugun niya in kawasa sin Iblis, amu in nakarā kamatay pa manga mānusiya'.",
        15: "Na, dayn ha sabab sin nahinang niya yan, natabang niya iban naīg niya in buga' sin manga tau mapatay. Sabab in kamatay amuna in kiyabubugaan sin manga tau salugay nila buhi', hangkan biya' sila sin sapantun kiyahuhukutan sin buga' nila.",
        16: "Na, matampal tuud isab sin bukun manga malāikat in tiyabang hi Īsa. Sagawa' biya' na sin kiyabayta' ha lawm Kitab, amu agi, “Tabangun niya in manga mānusiya', amu in biya' sin īman hi Ibrahim.”",
        17: "Na, in hāti niya subay hi Īsa mabiya' tuud sin kajarihanan sin kitaniyu pagkahi niya mānusiya' bat niya kalabayan in unu-unu katān kabinsanaan labayan sin manga mānusiya'. Subay yan kalabayan niya ha supaya siya mahinang Imam Dakula' magsuluhan kātu'niyu pa Tuhan ha supaya in dusa sin manga mānusiya' ampunun sin Tuhan. Kapangandulan siya iban maulung siya ha manga mānusiya'.",
        18: "Na, bihaun makatabang na siya ha manga tau, amu in nasasasat himinang sin mangī', sabab in siya baran niya nakalabay na nasasat iban nabinsana'.",
    },
    3: {
        1: "Na, hangkan manga taymanghud ku Almasihin, amu in napī' da isab sin Tuhan suku' niya, kannala niyu tuud in pasal hi Īsa. In siya piyakari kātu'niyu sin Tuhan, mahinang Imam Dakula' sin agama biyabawgbugan taniyu.",
        2: "Iyagad niya tuud hīnang in katān daakan kaniya sin Tuhan, amu in nagdaak kaniya huminang ha yan. Biya' da isab kan Musa in kata'gu niya maghinang sin diyaakan kaniya sin Tuhan magparuli ha manga tau napī' niya suku', amu in biya' sapantun bāy hiyulaan sin Tuhan.",
        3: "Sumagawa' labi mataas in kawasa hi Īsa dayn kan Musa. Bang ta hidalil ha paghinang bāy, labi bantug in naghinang sin bāy dayn sin bāy hīnang niya. Na, damikkiyan hi Īsa labi tuud in kalagguan niya dayn kan Musa.",
        4: "Na, kaingatan taniyu sin in katān bāy awn sadja taghinangan kaniya, sagawa' Tuhan in taghinangan sin unu-unu katān.",
        5: "Na, in hi Musa, hambuuk daraakun mata'gu ha hinang diyaakan kaniya sin Tuhan iban biyayta' niya in manga hibayta' sin Tuhan ha susūngun.",
        6: "Sagawa' in Almasi bukun sadja daraakun. Siya in tagkaputan sin Bāy sin Tuhan, sabab in siya amuna in Anak Tuhan. Mata'gu siya ha hinang diyaakan kaniya sin Tuhan. Na, in kitaniyu agad ha Almasi amuna in biya' bāy niya bang kitaniyu matawakkal iban maisug mangandul ha manga kiyajanji' sin Almasi kātu'niyu amu in hiyuhuwat-huwat natu'.",
        7: "Hangkan subay kitaniyu mamanduga sin bayta' sin Rū sin Tuhan siyulat ha lawm Kitab, amu agi, “Bang niyu karungugan ha adlaw ini in suwara sin Tuhan,",
        8: "ayaw kamu sumingud ha manga kaapu'-apuan niyu yadtu, amu in nagmatugas iban simulang sin kabayaan sin Tuhan. Karna' ha waktu sila duun ha hula' paslangan mahunit paghulaan piyanulay-sulayan nila in kawasa sin Tuhan.”",
        9: "“Duun nila siyulayan iban diyusta' in kawasa ku,” amu agi sin Tuhan, “minsan da kīta' nila na in tulung-tabang ku kanila ha lawm ka'patan tahun.",
        10: "Hangkan dimugal tuud aku ha manga tau yadtu iban nakaparman aku, laung ku, ‘In manga tau ini masi-masi harap pa dugaing in atay nila iban di' sila makay sin addat-tabīat diyaakan ku kanila.’",
        11: "Diyugalan aku sarta' nakasubali aku, laung ku, ‘Di' na tuud sila makasūd pa lawm hula' tiyatagama ku kanila, amu in masannyang paghulaan nila!’”",
        12: "Na, subay kamu maayad tuud, manga taymanghud ku, ha supaya kamu di' mahinang biya' sin manga tau sin masa yadtu. Adakala' awn duun kaniyu mangī' in pikilan iban di' magkahagad sarta' simiha' dayn ha Tuhan, amu in way kahinapusan niya.",
        13: "Na, biya' ha ini in hinangun niyu ha salugay awn pa waktu niyu dumungug sin suwara sin Tuhan pasal sin kalappasan niyu. Pagtabang-tiyabangi kamu manghindu' pakaniya-pakaniya dayn ha adlaw pa adlaw, ha supaya way minsan hambuuk kaniyu in kaakkalan marā sin sasat huminang sin mangī', iban magmatugas di' magad ha daakan sin Tuhan.",
        14: "Karna' in kitaniyu katān amuna in panāiban sin Almasi bang natu' gunggungan iban bawgbugan in pangandul natu' kaniya dayn ha panagnaan sampay pa kahinapusan.",
        15: "Amu ini in kiyabayta' ha lawm sin Kitab, “Bang niyu karungugan in suwara sin Tuhan ha adlaw ini, ayaw kamu sumingud ha manga kaapu'-apuan niyu yadtu, amu in nagmatugas iban simulang sin kabayaan sin Tuhan.”",
        16: "Hisiyu ta' in manga tau nasabbut ini, amu in nakarungug sin suwara sin Tuhan, sagawa' wala' nagkahagad kaniya? Na, sila na yan in manga tau amu in piyagnakuraan hi Musa, diyā minīg dayn ha Misir.",
        17: "Lāgi' hisiyu ta' in manga tau piyagmurkaan sin Tuhan ha lawm ka'patan tahun, bang bukun amu in manga tau nagdusa kaniya sarta' miyatay pasal sin dusa nila didtu ha hula' paslangan mahunit paghulaan.",
        18: "Iban hisiyu ta' in kiyugdan sin subali sin Tuhan, amu in laung niya, “Di' na tuud sila makasūd pa lawm hula' tiyatagama ku kanila, amu in masannyang paghulaan nila.”? Tantu in kiyugdan sin subali sin Tuhan amuna in manga tau simulang kaniya.",
        19: "Na, kaingatan natu' in sabab bang mayta' sila wala' nakasūd pa hula' kiyajanji' kanila sin Tuhan, sabab wala' sila nagparachaya kaniya.",
    },
    4: {
        1: "Na, bihaun kitaniyu na isab in tiyukbalan sin Tuhan janji' niya pasūrun pa lawm kasannyangan amu in piyag'iyan niya. Hangkan subay kitaniyu maayad ha supaya wayruun kātu'niyu in makabīn di' makaagad sumūd pa lawm kasannyangan kiyajanji' sin Tuhan.",
        2: "Karna' in kitaniyu nakarungug da isab sin Bayta' Marayaw amu in bakas diyungug sin manga kaapu'-apuan natu' sin masa nakauna yadtu. Diyungug nila in bayta' dayn ha Tuhan, sagawa' wayruun karayawan nakawa' nila, sabab pagdungug nila ha ini wala' sila nagparachaya iban nagkahagad.",
        3: "Na, in kitaniyu amu in magparachaya makasūd pa kasannyangan kiyajanji' sin Tuhan. Sumagawa' in manga di' magparachaya, di' makasūd, pasal biya' na sin kiyabayta' sin Tuhan, amu agi, “Diyugalan aku sarta' nakasubali aku, laung ku, ‘Di' na tuud sila makasūd pa hula' tiyagama ku kanila, amu in masannyang paghulaan nila!’” Namung in Tuhan biya' ha yan, bukun pasal bat wala' pa naawn in hula' piyag'iyan niya yan. Bukun tuud yan in puun-sabab, pasal in hula' yan asal naawn dayn ha tagna' pa kapapanjari sin Tuhan sin dunya.",
        4: "Kiyaiingatan natu' sin asal naawn in hula' kiyajanji' sin Tuhan, pasal awn kiyasulat ha lawm Kitab, amu agi, “Ha hikapitu sin adlaw in Tuhan himundung na dayn ha hinang niya sabab naubus niya na piyapanjari in katān.”",
        5: "Sagawa' minsan bihādtu, in manga tau amu in wala' nagkahagad ha Tuhan, wala' da nakasūd pa hula' kiyajanji' kanila sin Tuhan, sabab biyalikan sin Tuhan in kiyapamung niya, amu agi, “Di' tuud sila makasūd pa lawm hula' tiyatagama ku kanila, amu in masannyang nila paghulaan.”",
        6: "Malayngkan minsan bihādtu, wala' nagbaluba in janji' sin Tuhan ha manga mānusiya'. Pagga in manga tau amu in nakarungug muna sin Bayta' Marayaw, wala' nakasūd pa hula' kiyajanji' sin Tuhan kanila, sabab wala' sila nagparachaya kaniya, na ha susūngun awn da isab manga tau pasūrun sin Tuhan pa lawm hula' masannyang paghulaan amu in kiyajanji' niya.",
        7: "Na, in pasal yan kaingatan natu' sabab in Tuhan dimihil na isab waktu ha manga tau tumayma' sin janji' niya, lāgi' in waktu yan amuna in bihaun. Hangkan nakalabay mayan bukun na pila tahun in masa sin manga tau, amu in wala' nagparachaya ha Tuhan, piyapamung sin Tuhan kan Daud in bichara niya, amu in kiyasulat ha lawm Kitab bakas ku na nasabbut kaniyu, amu agi, “Bang niyu karungugan in suwara sin Tuhan ha adlaw ini, ayaw kamu magmatugas sadja.”",
        8: "Na, dayn ha ini kaingatan taniyu sin in hula' piyagdāhan hi Yussa' ha manga tau sin masa yadtu, bukun amu in hula' kiyajanji' sin Tuhan kanila, amu in masannyang nila paghulaan. Pasal bang amuna yan in hula' kiyajanji' sin Tuhan, na tantu di' niya na sabbutun magbalik in janji' niya.",
        9: "Na, pagga biya' ha yan in hāl niya, in hāti niya masi pa awn lugal sin manga tau suku' sin Tuhan sumūd pa lawm hula', amu in masannyang nila paghulaan iban Tuhan, biya' sin kasannyangan sin Tuhan ha hikapitu sin adlaw pag'ubus niya nagpapanjari sin unu-unu katān.",
        10: "Karna' hisiyu-siyu in makasūd pa lawm hula' masannyang kiyajanji' sin Tuhan, in siya yan sumannyang na dayn ha unu-unu hinang niya, biya' da isab sin kasannyangan sin Tuhan naubus niya mayan piyapanjari in unu-unu katān.",
        11: "Hangkan subay kitaniyu tumuyu' tuud magad sin dān sin hikasūd natu' pa lawm hula' masannyang yan, ha supaya wayruun dayn kātu' minsan hambuuk in mahinang biya' sin manga tau sin masa yadtu, amu in wala' nakasūd pa hula' kiyajanji' sin Tuhan kanila pasal kulang in parachaya iban īman nila kaniya.",
        12: "In Parman sin Tuhan amu in puunan sin kabuhi' salama-lama, landu' makusug humūp pa lawm atay iban nyawa sin tau. Biya' yan sapantun sin pakukus duwa sulab niya, sagawa' labi pa mahayt dayn ha pakukus. Lumagbas yan dayn ha luluatan sampay pa sumsum sin ginhawa-baran sin mānusiya'. Hangkan in Parman sin Tuhan, amu in makapaingat iban makapatampal sin unu-unu katān ha lawm pikilan iban atay sin mānusiya'.",
        13: "Na, lāgi' wayruun unu-unu in hikatapuk dayn ha Tuhan sabab kaingatan niya tuud marayaw in unu-unu na mayan pasal sin manga katān piyapanjari niya. Iban ha susūngun subay in kitaniyu katān mamayta' kaniya sin katān nahinang iban napikil natu'.",
        14: "Pagga in Imam natu' Dakula', Imam makawasa, amuna hi Īsa, amu in Anak Tuhan, lāgi' yadtu na siya nagbalik pa haddarat sin Tuhan, hangkan subay natu' pakusugun iban pahugutun in pagparachaya natu' kaniya.",
        15: "Karna' in hi Īsa, amu in Imam natu' Dakula', maulung kātu'niyu pasal kiyaiingatan niya in kitaniyu mānusiya' maguya' in pamaranan iban pangatayan. Hangkan niya ini kaingatan pasal in siya bakas dī ha dunya nagbaran mānusiya', lāgi' kiyalabayan niya in ginisan sasat biya' sin manga sasat magdatung pa kātu'niyu mānusiya', sagawa' in siya wala' narā sin sasat sin saytan.",
        16: "Na, hangkan, pagga siya in Imam natu' Dakula', subay natu' lawaun in buga' natu' sumuuk pa haddarat sin Tuhan, amu in puunan sin katān tulung-tabang. Duun taniyu kananaman in ulung niya kātu'niyu, lāgi' kabaakan in tulung-tabang niya ha waktu taniyu magkagunahan.",
    },
    5: {
        1: "Na, hisiyu-siyu in tau hinangun Imam Dakula' sin bangsa Yahudi, pīun siya dayn ha manga tau pagkahi niya. Ampa in tau mahinang Imam Dakula' amuna in mahinang suluhan sin manga tau pa Tuhan. Siya in huminang sin manga lalabutan iban hayup pagkulbanan sin manga tau pa Tuhan, ha supaya ampunun sin Tuhan in dusa sin manga tau.",
        2: "Na, pagga in Imam Dakula' mānusiya' da isab datungan lamma, na maingat siya humanunut ha manga tau wayruun panghāti nila iban amu in simisiha' dayn ha dān tudju pa Tuhan.",
        3: "Iban dayn ha sabab mānusiya' da isab siya, amu in magpakahinang sadja kasāan, na subay da isab siya tumukbal sin hayup pagkulbanan, bukun sadja ha tungud sin dusa sin manga tau, sagawa' sampay da isab ha tungud sin dusa niya.",
        4: "Wayruun tau in makapagbaya' mahinang siya Imam Dakula', karna' Tuhan in magpī' sin tau dihilan niya sin kalagguan yan iban sin kawasa yan biya' kan Harun, amu in napī' niya Imam Dakula' sin timpu nakauna yadtu.",
        5: "Damikkiyan, in hi Īsa wala' dimihil kalagguan pa baran niya mahinang siya Imam Dakula'. Sagawa' nagparman in Tuhan kaniya, amu agi, “In ikaw Anak ku. Iban dayn ha adlaw ini, in aku amuna in Ama' mu.”",
        6: "Iban kiyabayta' pa isab ha ayat dugaing sin in Tuhan namung sin biya' ha ini, amu agi, “Ikaw na in mahinang imam suluhan, umurul sin limpa' siki hi Malkisadik. Iban kasaumulan kaw mag'imam suluhan.”",
        7: "Ha waktu dī pa hi Īsa ha dunya, masuhul magtangis tuud siya bang siya mangayu' na duwaa iban junjung pa Tuhan, amu in makalappas kaniya dayn ha kamatay. Diyungug sin Tuhan in pagpangayu' niya duwaa, sabab mababa' in pangatayan niya, lāgi' nagmamabuga' tuud siya pa Tuhan.",
        8: "Malayngkan minsan siya Anak Tuhan, limabay da isab siya kabinsanaan, amu in nakahindu' kaniya bang biya' diin tuud in pagkahagad ha Tuhan.",
        9: "Na, natikmud niya mayan hīnang in katān daakan kaniya sin Tuhan, siya na in nahinang manglalappas ha tau katān amu in magparachaya kaniya. Iban siya in dumihil kanila kabuhi' salama-lama.",
        10: "Lāgi' siya in hīnang sin Tuhan Imam Dakula' biya' sin pag'imam hi Malkisadik.",
        11: "Iban mataud pa in kabayaan ku hipamung ha pasal sin kahālan ini, sagawa' mahunit ini hibayta' kaniyu pasal bukun na marayaw in panghāti niyu.",
        12: "Na, in tūp niya, in kamu yan manghindu' na pa kaibanan sin manga kiyaingatan niyu, sabab malugay na kamu miyamagad kan Īsa. Sagawa' in kamu yan masi subay hinduan sin undang-undang pasal sin bayta' dayn ha Tuhan, sabab wala' niyu pa yan kiyahātihan tuud, karna' in kamu yan biya' sapantun manga bata'-bata' asibi', amu in nagdururu' pa, iban di' pa makakaun sin kakaun matugas. (Hāti niya in kamu yan di' pa makahāti sin hindu' malawm.)",
        13: "Na, hisiyu-siyu in biya' bata'-bata', amu in di' pa makakaun sin unu-unu matugas dugaing dayn ha gatas, na in hāti niya, in siya yan biya' da isab hambuuk bata'-bata', amu in di' pa maingat magpabuntul sin hinang niya, pasal kulang pa in panghāti niya sin mangī' iban marayaw.",
        14: "Hangkan bang ta hidalil ha pagkaun, in kakaun matugas, amu in hindu' malawm, suku' sadja sin manga tau, amu in makusug in pangandul pa Tuhan, lāgi' maingat iban biyaksa na sumilang sin mangī' iban marayaw.",
    },
    6: {
        1: "Na, hangkan (pagga kitaniyu malugay na Almasihin), subay natu' hisūng in pagpangadji' natu' pasal sin Almasi. Subay natu' pangadjiun na in manga hindu' malawm, bukun dumuun na sadja kitaniyu ha bakas natu' na napangadji', amu in manga undang-undang sin hindu' pasal sin Almasi. Di' natu' na kagunahan pangadjiun magbalik in manga hindu' biya' na sin paglawak dayn ha manga hinang way kapūsan, amu in di' makarā kātu' pa kalappasan iban pasal sin pagparachaya pa Tuhan.",
        2: "Lāgi' kiyaiingatan natu' na in hindu' pasal sin pagsuchi amu in pag'ayl iban pagligu' iban pasal sin pagdupun ha ū sin tau pangayuan duwaa pa Tuhan bang mayan hūpun sin Rū sin Tuhan. Damikkiyan kaingatan natu' da isab in hindu' pasal sin pagbuhi' magbalik ha manga patay iban sin hukuman ha adlaw mahuli, amu in di' na mapinda kasaumulan.",
        3: "Hangkan subay natu' hisūng in pagpangadji' natu' pasal sin Almasi. Na, amu yan in hinangun natu' bang dumūl da in Tuhan.",
        4: "Karna' in manga tau, amu in namutawan sin īman nila ha Almasi, kahunitan na magtawbat magbalik sin dusa nila. Pasal bakas na kiyarihilan sin Tuhan kasawahan in panghāti nila. Kiyananaman nila na in karayawan kiyarihil kanila sin Tuhan biya' sin karayawan ha surga', iban bakas na sila hiyūp sin Rū sin Tuhan.",
        5: "Iban bakas nila kiyapamintangan in karayawan sin Parman sin Tuhan, iban kīta' nila na in kusug sin kawasa sin Tuhan, amu in magmattan na tuud ha masa susūngun.",
        6: "Malayngkan minsan nila kiyaingatan na in katān yan, biyutawanan nila da in īman nila ha Almasi. Na, in manga tau biya' ha yan, way na dān nila magtawbat magbalik sin dusa nila, sabab dayn ha pasal sin nahinang nila yan, biya' nila da liyansang nagbalik pa usuk in amu in Anak Tuhan iban hīna' ha katauran sin tau.",
        7: "Na, bang ta dalilun in mānusiya' pa hambuuk lupa' piyag'uumahan, biya' ha ini in hantang niya. Apabila in lupa' sin uma yan mawmu hiyuhūp sin ulan, in pananum ha lupa' yan tumubu' iban magbunga marayaw, amu in hikapagguna iban hikarayaw parasahan sin tagdapu. Damikkiyan, in tau amu in magpahūp sin Parman sin Tuhan pa lawm pamikil iban atay niya, tartantu marayaw sadja in hinang niya iban anugharaan tuud siya sin Tuhan.",
        8: "Sumagawa' bang in lupa' yan tiyutubuan sadja sin manga sagbut iban lukut lappas, na in lupa' yan wayruun guna niya iban matūp da'pugan sin kāyu. Damikkiyan in tau amu in di' magparuli iban magkahagad sin daakan sin Almasi, pagmurkaan siya sin Tuhan iban masiksa' siya ha adlaw mahuli.",
        9: "Na, malayngkan, manga bagay ku kakasihan, minsan isab aku nagbichara biya' ha yan, natatantu ku da isab sin bukun biya' ha yan in palangay niyu. Kiyaiingatan ku sin mahugut in īman niyu iban marayaw in hinang niyu. Na, in yan amuna in tanda' sin awn na kalappasan niyu.",
        10: "In Tuhan mabuntul tuud. Di' niya kalupahan in manga nahinang niyu marayaw, atawa in lasa niyu kaniya, amu in piyakita' niyu kaagi sin pagtabang niyu ha manga pagkahi niyu Almasihin sampay pa bihaun.",
        11: "Na, hangkan in kabayaan namu' tuud, di' mabugtu' in tuyu' sin pakaniya-pakaniya kaniyu magad ha hindu' sin Almasi ha salugay niyu buhi', ha supaya magmakbul in iyaangut niyu dayn ha Tuhan.",
        12: "In kabayaan namu', di' kamu maglisu'-lisu', sagawa' in kabayaan namu' mabiya' kamu sin manga tau amu in makusug in parachaya iban pangandul, lāgi' siyandalan nila in katān haggut-pasu'. Hangkan matabuk nila in kiyajanji' sin Tuhan kanila.",
        13: "Na, yari in hambuuk tanda' sin kasabunnalan sin pamung yan. Ha masa nakauna yadtu awn kiyajanji' sin Tuhan kan Ibrahim. Sarta' simapa siya dayn ha ngān niya tuud, karna' wayruun na unu-unu masabbut niya mataas pa dayn ha ngān niya, sin makbulun niya tuud in kiyajanji' niya.",
        14: "Nagparman in Tuhan, amu agi. “Ini in janji' ku kaymu. Dihilan ta kaw tuud karayawan iban pataurun ku in manga panubu' mu.”",
        15: "Hi Ibrahim wala' siyumu nagtagad sin janji' sin Tuhan. Hangkan natabuk niya in katān kiyajanji' sin Tuhan kaniya.",
        16: "In addat sin manga tau bang sila sumapa, sumabbut sila ngān sin Tuhan, amu in mataas dayn ha unu-unu katān. Na, bang ngān sin Tuhan na in masabbut, in unu-unu parakala' humatul na.",
        17: "Na, mabaya' isab hipahāti tuud marayaw sin Tuhan pa manga tau kiyajanjian niya, sin di' niya tuud pindahan in namaksud niya hinangun. Hangkan siyapahan niya dayn ha ngān niya in janji' niya.",
        18: "Na, in janji' iban sapa sin Tuhan tantu tuud di' mapinda sabab in Tuhan di' tuud magputing. Hangkan in kitaniyu amu in simangdul sin baran natu' pa Tuhan, kumusug in huwat-huwat natu' ha janji' hirihil niya kātu'niyu.",
        19: "Bang ibārat bahudji' atawa sāw, in huwat-huwat natu' ha janji' sin Tuhan awn na siyagnatan niya mahugut. Way kapiligruhan, sabab in siyagnatan sin huwat-huwat natu' amuna in hi Īsa. Lāgi' in siya yadtu na miyuna dayn kātu'niyu pa surga' ha haddarat sin Tuhan, sumapāat kātu'niyu dayn ha manga dusa taniyu. In pagkadtu niya pa surga' pa haddarat sin Tuhan biya' sapantun sin pagsūd sin imam Yahudi pa lawm bilik landu' tuud suchi amu tiyatamingan sin kurtina marakmul. Na, hi Īsa na in Imam Dakula', magsuluhan kātu'niyu pa Tuhan biya' sin bakas hīnang hi Malkisadik sin timpu nakauna yadtu, iban siya na in mag'imam suluhan kasaumulan.",
        20: "Bang ibārat bahudji' atawa sāw, in huwat-huwat natu' ha janji' sin Tuhan awn na siyagnatan niya mahugut. Way kapiligruhan, sabab in siyagnatan sin huwat-huwat natu' amuna in hi Īsa. Lāgi' in siya yadtu na miyuna dayn kātu'niyu pa surga' ha haddarat sin Tuhan, sumapāat kātu'niyu dayn ha manga dusa taniyu. In pagkadtu niya pa surga' pa haddarat sin Tuhan biya' sapantun sin pagsūd sin imam Yahudi pa lawm bilik landu' tuud suchi amu tiyatamingan sin kurtina marakmul. Na, hi Īsa na in Imam Dakula', magsuluhan kātu'niyu pa Tuhan biya' sin bakas hīnang hi Malkisadik sin timpu nakauna yadtu, iban siya na in mag'imam suluhan kasaumulan.",
    },
    7: {
        1: "In hi Malkisadik ini amu in sultan sin hula' Salam sin masa nakauna yadtu iban amu in Imam Dakula' nagsuluhan ha manga tau pa Tuhan Mahatinggi. Manjari hambuuk waktu diyaug hi Ibrahim nagbunu' in (upat) sultan kuntara niya. Sakali pag'uwi' niya dayn ha pagbunuan, biyāk siya hi Malkisadik sarta' piyangayuan siya duwaa pa Tuhan kaagi hi Malkisadik.",
        2: "Na, imungsud siya jakat kan Malkisadik, harga' hangka-bahagi' sin hangpu'ka-bahagi' sin katān alta' nakawa' niya dayn ha pagbunuan. (In maana sin ngān hi Malkisadik, “Sultan Maādil”. Iban pagga siya Sultan sin hula' Salam awn isab dugaing maana sin ngān niya, amu in sultan makarihil kasannyangan ha manga tau.)",
        3: "In hi Malkisadik ini, wayruun kiyabayta' pasal sin ina'-ama' niya, atawa sin manga kaapu'-apuan niya, iban wayruun kiyabayta' pasal sin kapag'anak atawa kamatay kaniya. Na, amu yan in sabab hangkan in pag'imam suluhan niya makajari iyanun wayruun kahinapusan niya biya' da isab sin pag'imam suluhan hi Īsa, amu in Anak Tuhan.",
        4: "Na, kaingatan niyu na in kalagguan hi Malkisadik, karna' minsan in hi Ibrahim, amu in tau bantug nanubu' kātu'niyu imungsud da sin jakat niya kan Malkisadik dayn ha katān alta' nakawa' niya dayn ha pagbunuan.",
        5: "Na, in manga panubu' hi Libi amuna in manga tau nahinang imam suluhan sin manga tau pa Tuhan ha masa nakauna yadtu, iban kiyarihilan sila kapatutan sin sara' agama tumabuk jakat dayn ha pagkahi nila Yahudi, minsan amu in panubu' da isab sin Ibrahim.",
        6: "In hi Malkisadik bukun hambuuk panubu' hi Libi, sagawa' imungsud jakat hi Ibrahim kaniya. Lāgi' piyangayuan niya duwaa pa Tuhan hi Ibrahim, minsan in hi Ibrahim amura in tau kiyajanjian sin Tuhan.",
        7: "Na, dayn ha sabab yan kaingatan taniyu mataas in kawasa hi Malkisadik dayn kan Ibrahim, sabab bang ha addat sin bangsa ta, mataas in kawasa sin tau mangayu' duwaa pa Tuhan dayn sin tau pangayuan niya duwaa.",
        8: "In manga imam suluhan panubu' hi Libi amu in pag'uungsuran jakat sin manga tau, mānusiya' da isab biya' kātu'niyu amu in magkamatay da. Sagawa' in hi Malkisadik amu in iyungsuran hi Ibrahim sin jakat niya, bukun siya biya' sin manga imam yan, sabab in kiyabayta' ha lawm Kitab, in siya masi buhi'.",
        9: "Na, bang sayuhun ha waktu imungsud hi Ibrahim sin jakat niya kan Malkisadik, in hi Libi amu in nanubu' ha manga imam pag'uungsuran jakat, biya' da isab siya nakaungsud jakat kan Malkisadik baran niya, sabab in siya hambuuk panubu' hi Ibrahim.",
        10: "Karna' minsan wala' pa piyag'anak hi Libi sin waktu kapagbāk hi Ibrahim kay Malkisadik, amu in pag'iyanun biya' da sila nakapagbāk kay Malkisadik, pasal in hi Libi biya' sapantun binhi' ha lawm baran hi Ibrahim ha waktu kapagbāk nila kay Malkisadik, sabab in siya nanubu' dayn kan Ibrahim. (Na, hangkan kaingatan taniyu mataas in kawasa hi Malkisadik dayn ha kawasa hi Libi.)",
        11: "Na, sin masa nakauna yadtu ha waktu piyanaug sin Tuhan in sara' niya pa bangsa natu', hīnang niya imam suluhan hinda Libi iban sin manga panubu' niya, amu in nagkaput iban nagpapanaw sin sara' niya. Sumagawa' in hinang sin manga panubu' hi Libi, wala' nakarā ha manga tau pa dān mabuntul tudju pa Tuhan. Hangkan magkalagihan palahilun in hambuuk tau mag'imam suluhan ha manga tau pa Tuhan, amu in biya' pag'imam hi Malkisadik, bukun biya' kan Harun, amu in hambuuk imam panubu' hi Libi.",
        12: "Na, pagga in pag'imam suluhan sin manga panubu' hi Libi giyantian na sin tau dugaing, na in hāti niya pindahan da isab in sara' iyaagad sin bangsa taniyu.",
        13: "Na, in tau piyagbichara ku, (amu in gumanti' ha manga panubu' hi Libi mag'imam suluhan,) amuna in Panghu' ta Īsa Almasi. In siya ini bukun guwa' dayn ha pihak hi Libi, lāgi' wayruun tau dayn ha pihak niya in kiyarihilan kawasa mag'imam suluhan.",
        14: "Iban kiyaiingatan sin katān, sin in hi Īsa panubu' dayn ha pihak hi Yudah. Ampa hi Musa wala' nakasabbut sin pihak ini ha waktu namichara siya pasal sin pag'imam.",
        15: "Hangkan matampal na tuud kātu' (sin pindahan na sin Tuhan in sara' niya), sabab awn na piyalahil sin Tuhan tau dugaing mag'imam suluhan amu in biya' kan Malkisadik.",
        16: "Na, in Almasi nahinang imam suluhan bukun pasal sin pangkat nanubu' kaniya, sagawa' nahinang siya imam suluhan sabab sin kawasa niya iban sin kabuhi' niya way kahinapusan.",
        17: "Karna' kiyabayta' ha lawm Kitab, amu agi, “Ikaw na in mahinang imam suluhan biya' kan Malkisadik. Iban in pag'imam suluhan mu kasaumulan.”",
        18: "Na, hangkan in sara' nakauna pīndahan na sin Tuhan, pasal wayruun da kusug iban wala' nakaamu.",
        19: "Karna' in sara' sin Tuhan piyanaug dayn kan Musa, wala' da nakarihil kamakbulan ha maksud sin Tuhan ha manga mānusiya'. Sagawa' bihaun awn na huwat-huwatun natu' labi tuud marayaw dayn sin sara' nakauna, sabab awn na aturan ba'gu kiyarihil kātu'niyu, amu in makarā kātu'niyu sumuuk pa Tuhan.",
        20: "Lāgi' in aturan ba'gu ini labi tuud marayaw, sabab simapa in Tuhan ha waktu kahinang niya kan Īsa imam suluhan. Sagawa' ha waktu kahinang imam suluhan ha manga panubu' hi Libi sin masa nakauna yadtu, in Tuhan wala' simapa.",
        21: "Na, in hi Īsa nahinang imam suluhan sabab dayn ha sapa sin Tuhan. Kiyasulat ha lawm Kitab, amu agi, “In Tuhan simapa iban tantu di' na mapinda in pamikil niya sin pasal ini, amu agi, ‘Ikaw na in mag'imam suluhan kasaumulan!’”",
        22: "Na, dayn ha sabab simapa in Tuhan kan Īsa sin siya in mag'imam suluhan kasaumulan, na piyangakuhan hi Īsa in kamakbulan sin paljanjian ba'gu sin Tuhan pa manga mānusiya'. Lāgi' in sara' sin paljanjian ba'gu ini, labi tuud marayaw dayn sin sara' nakauna piyanaug sin Tuhan dayn kan Musa.",
        23: "Awn pa isab dugaing piyagbiddaan sin pag'imam hi Īsa iban sin manga panubu' hi Libi. In manga kaimaman panubu' hi Libi mataud, karna' bang mapatay in hambuuk imam awn dugaing gumanti'. Magkabugtu' sadja in hinang nila.",
        24: "Sumagawa' in pag'imam suluhan hi Īsa kasaumulan. Wayruun tau makaganti' kaniya mag'imam suluhan, pasal in siya buhi' kasaumulan.",
        25: "Na, hangkan dayn ha sabab yan, malappas hi Īsa in manga tau, amu in mangayu' kaampunan ha Tuhan, bang sila mangandul kaniya. Lāgi' in pagpanglappas niya yan, bukun sadja ha bihaun, sagawa' sampay pa kasaumulan, sabab in siya buhi' salama-lama, nangangayu' junjung pa Tuhan ha pasal nila.",
        26: "Na, mattan na tuud sin hi Īsa in Imam Dakula' kalagihan natu' magsuluhan kātu'niyu pa Tuhan, sabab in siya suchi, iban wayruun unu-unu kangīan atawa tamak-tawktuk kabaakan duun kaniya. Lāgi' kiyandī na siya sin Tuhan dayn ha katān mānusiya' baldusa. Naangkat na siya pa surga' iban kiyarihilan na sin salaggu'-laggu' kawasa iban kalagguan.",
        27: "In hi Īsa bukun biya' sin manga kaibanan Imam Dakula', amu in subay magsumbay' hayup adlaw-adlaw pagkulbanan muna-muna ha tungud sin dusa nila, ubus ampa dusa sin manga tau, ha supaya sila ampunun sin Tuhan. Na, in yan bukun na wajib hinangun hi Īsa, nagminsan niya da iyungsud in dugu'-nyawa niya pa Tuhan, giyanti' kulban bat ampunun sin Tuhan in dusa sin manga mānusiya'.",
        28: "Ha pagpī' sin manga imam suluhan sin masa nakauna yadtu, iyagad nila in sara' amu in piyanaug sin Tuhan dayn kan Musa. Sagawa' in manga tau napī' nag'imam suluhan, mānusiya' da isab, biya' kātu' amu in asal taga salla' iban kasāan. Sagawa' dugaing na bihaun pasal jimanji' in Tuhan sarta' siyapahan niya sin in Anak niya, amuna in mag'imam suluhan ha manga mānusiya' pa Tuhan, karna' in siya tubus ha katān. Lāgi' in pag'imam suluhan niya masampurna' sin Tuhan kasaumulan.",
    },
    8: {
        1: "In kamaksuran tuud sin piyagbichara ku ini kaniyu, magpahāti kaniyu sin awn na Imam natu' Dakula', biya' sin nasabbut ku kaniyu hayn-duun. In Imam Dakula' ini amuna in hi Īsa, amu in yadtu bihaun ha surga' limilingkud ha dapit pa tuu sin Tuhan Mahatinggi.",
        2: "Lāgi' yadtu siya bihaun ha surga' nag'iimam suluhan kātu' pa Tuhan, didtu ha lugal landu' tuud suchi, amu in asal puunan langgal piyaawn sin Tuhan, bukun hīnang sin mānusiya'.",
        3: "Na, in katān imam dakula' sin masa nakauna yadtu kiyarihilan sin hinang magpasampay sin manga lalabutan iban sin manga hayup pagkulbanan sin manga tau pa Tuhan. Na, damikkiyan in hi Īsa, amu in Imam natu' Dakula', subay da isab awn hikaungsud niya pa Tuhan ha pasalan sin manga tau.",
        4: "Malayngkan, bang hi Īsa dī ha dunya, di' tuud siya mahinang imam suluhan pasal awn na manga imam suluhan dī ha dunya masi miyamagad sin sara' nakauna, amu in sara' sin manga Yahudi ha palihālan sin pagdihil lalabutan pa Tuhan.",
        5: "In hinang sin manga imam suluhan ha lawm langgal dī ha dunya, biya' yan hantang lambung sadja, sabab in yan singuran dayn ha hinang didtu ha surga'. Hangkan natu' yan kaingatan, sabab awn kiyasulat ha lawm Kitab pasal sin paghinang hi Musa sin bāy pagtataatan, amu in hīnang dayn ha pais hayup sin masa nakauna yadtu, amu agi sin Tuhan kaniya, “Tantuha tuud sin in langgal hinangun mu makasingud tuud sin papata sin suntuan sin langgal piyakita' ku kaymu duun ha taas būd.”",
        6: "Sagawa' ha bihaun hi Īsa bilang imam suluhan labi tuud mataas in hinang niya dayn sin hinang sin manga imam miyamagad sin aturan sin paljanjian nakauna. Damikkiyan in paljanjian ba'gu hīnang sin Tuhan, amu in piyasampay mari kātu'niyu hi Īsa, labi marayaw dayn sin paljanjian nakauna, pasal in paljanjian ba'gu biyaktul dayn ha manga janji' sin Tuhan labi marayaw.",
        7: "Lāgi' bang in paljanjian nakauna bat wayruun salla' niya, na di' na yan gantian sin Tuhan sin dugaing.",
        8: "Sagawa' in Tuhan wala' kiyasulutan sin hinang sin manga tau niya (amu in miyagad sin aturan sin paljanjian nakauna). Hangkan biya' na sin kiyabayta' ha lawm Kitab, nagparman in Tuhan amu agi, “Dungug kamu. Awn da waktu dumatung ha susūngun, palahilun ku in aturan sin paljanjian ba'gu mawn pa manga bangsa Yahudi katān, amu in naghuhula' ha Israil iban ha hula' Yudah.",
        9: "In aturan sin paljanjian ba'gu ini bukun biya' sin aturan piyalahil ku mawn tagna' pa kaapu'-apuan nila ha waktu diyā ku sila gimuwa' dayn ha Misir, amu in wala' nila da naagad hīnang. Na, hangkan piyasāran ku na sila,” laung sin Panghu' Tuhan.",
        10: "“Na, bihaun biya' ha ini in aturan sin paljanjian ba'gu panaugun ku pa manga bangsa Israil. Pagdatung sin waktu palahilun ku in aturan sin paljanjian ba'gu ini,” laung sin Tuhan Panghu', “papahūpun ku in manga sara' ku pa lawm pamikil nila, iban hiukkil ku ha lawm bigi jantung nila. Na, aku na in Tuhan pagtuhanan nila tuud, iban sila na in manga tau agad tuud kāku'.",
        11: "Na, bang lumahil na in paljanjian ba'gu yan, bukun na wajib kanila in mamayta' ha pagkahi nila atawa panāiban nila sin pasal ku. Karna' in sila katān dayn ha tau baba' pa tau mataas, makaingat na kāku'.",
        12: "Lāgi' ampunun ku na in manga dusa nila iban di' ku na tumtumun in manga nahinang nila kangīan.”",
        13: "Na, pagga nasabbut na sin Tuhan in aturan sin paljanjian ba'gu, in hāti niya, pīndahan na sin Tuhan in aturan sin paljanjian nakauna, pasal in yan biya' sapantun pannyagaan amu in pasaw na. Na, tiyap-tiyap sin unu-unu pasaw, in hāti niya di' na hikapaglagi.",
    },
    9: {
        1: "Na, in aturan sin paljanjian nakauna awn manga sara' niya pasal sin pagtaat pa Tuhan iban awn da isab bāy pagtataatan hīnang sin manga tau pagtaatan nila.",
        2: "Hīnang nila (dayn ha manga pais hayup) in bāy pagtataatan. In bilik panagnaan, amu in dapit pa guwa', amuna in kiyaruruunan sin palitaan pitu in sanga niya, iban sin lamisahan piyagbubutangan sin tinapay ha babaw niya, amu in tinapay lalabutan sin bangsa Yahudi pa Tuhan. In bilik ini amuna in pagtawagun bilik suchi.",
        3: "Manjari awn isab kurtina imuutlang sin bilik ini iban sin bilik hikaruwa, amu in pagtawagun bilik landu' tuud suchi.",
        4: "Na, duun ha bilik yan, awn lamisahan bulawan, amu in panugtugan kamanyan, iban hambuuk baul pagtawagun “Baul sin Paljanjian” amu in piyuputus sin bulawan pa lawm pa guwa'. In ha lawm sin baul awn hambuuk garul bulawan taga luun kakaun pagtawagun “manna”. Iban duun da isab ha lawm baul yan in tungkud hi Harun, amu in tiyubuan manga dahun. Iban duun da isab kiyabutang in duwa batu papad, amu in iyuukkilan sin aturan sin paljanjian nakauna, amu in sara' daakan sin Tuhan pa manga mānusiya'.",
        5: "Ha babaw sin baul bulawan awn duwa tau-tau biya' dagbus malāikat taga pikpik, amu in tanda' pangilāhan sin yaun duun in haddarat sin Tuhan. Kiyatatabunan sin pikpik nila in saub sin baul, amu in lugal pag'aampunan sin Tuhan sin dusa sin tau. Na, sagawa' bihaun bukun pa waktu hipagtaki-taki sin unu-unu katān.",
        6: 'Na, bihayan in kaagi sin pagbutang sin manga kapanyapan ha lawm sin bāy pagtataatan. Na, in manga imam adlaw-adlaw sumūd pa bilik ha unahan amu in lugal suchi, maghinang sin kiyawajib kanila.',
        7: "Sagawa' hambuuk da tau in makasūd pa bilik hikaruwa amu in lugal landu' tuud suchi. In tau makasūd ini amura in Imam Dakula', lāgi' makaminsan da siya makasūd pa bilik ini ha lawm sin hangka-tahun. Iban di' siya makasūd pa bilik ini bang siya di' magdā sin dugu' sin hayup piyagkulbanan. In dugu' sin hayup ini tiyukbal pa Tuhan ha supaya ampunun sin Tuhan in dusa sin imam iban sin dusa sin manga tau, amu in nagdusa ha wala' nila kiyaingatan.",
        8: "Na, dayn ha aturan sin pagtaat ini, piyahāti tuud kātu'niyu sin Rū sin Tuhan, sin wala' pa naukab ha tau katān in bilik landu' tuud suchi ha sakainu timitindug pa in bilik ha guwa'.",
        9: "Na, in ini hambuuk pamintangan taniyu ha masa ini. Karna' ha paljanjian nakauna, minsan in manga tau dimihil lalabutan iban timukbal hayup pagkulbanan pa Tuhan, in manga ini wala' da nakapasannyang sin lawm pamikil nila pasal wala' da miyuntul in lawm atay iban i'tikad nila tudju pa Tuhan.",
        10: "Na, hangkan bihādtu, sabab in sara' daakan iyaagad nila pasal sadja sin manga kakaun iban iinumun, amu in hiyaram sin agama nila, iban pasal sin manga ginisan paghugas-hugas hipagsuchi sin baran nila. In manga sara' daakan yan kalagihan sadja hipagsuchi sin baran sin tau, sagawa' bukun sin lawm atay. Na, in sara' daakan yan, kalagihan sadja ha salugay wala' pa napanaug sin Tuhan in paljanjian ba'gu.",
        11: "Na, sagawa' limahil mayan mari in Almasi, siya na in nahinang Imam Suluhan Dakula' magpapanaw sin paljanjian ba'gu, amu in dimirihil na karayawan kātu'niyu bihaun. Lāgi' in lugal piyaghinangan niya bilang hambuuk suluhan, umbulsatu tuud in dayaw. Way sibu' niya, sabab bukun yan hinangan sin mānusiya', iban bukun agad dī ha dunya ini in kiyabutangan sin lugal yan.",
        12: "Pagsūd sin Almasi pa lugal yan, amu in biya' hantang sin bilik landu' tuud suchi hīnang sin manga tau, nagminsan da siya simūd, wala' na kiyabalikan. Lāgi' pagsūd niya, wala' siya nagdā dugu' sin manga kambing atawa sapi' hiungsud pagkulbanan biya' sin hinang sin manga imam dakula' ha dunya. Sagawa' in iyungsud niya pa Tuhan in dugu'-nyawa niya tuud ha kalansang kaniya pa usuk, ha supaya kitaniyu makabāk na sin kalappasan iban kaampunan dayn ha Tuhan amu in tumatas sampay kasaumulan.",
        13: "Na, ha lawm sara' sin paljanjian nakauna, bang in dugu' sin kambing atawa sapi', atawa abu sin anak sapi' siyunug liyalamuran tubig hipangligsik pa baran sin tau nababa'tal, na mapuas na in ba'tal niya sarta' mahalal na in sambahayang niya.",
        14: "Sagawa' labi marayaw iban makusug in mahinang sin dugu' sin Almasi dayn ha dugu' sin manga hayup, sabab in siya tubus wayruun tuud tamak-tawktuk. Dayn ha tulung-tabang sin Rū sin Tuhan, amu in asal way kahinapusan niya, iyungsud hi Īsa in dugu'-nyawa niya pa Tuhan, ha supaya muntul in lawm atay iban i'tikad natu' tudju pa Tuhan, lāgi' di' na maghinang sin manga ginis-ginisan amu in wayruun da kapūsan, di' makarā kātu'niyu pa Tuhan. Iban ha supaya kitaniyu makahinang na sin kiyamaksud kātu'niyu sin Tuhan, amu in buhi' salama-lama.",
        15: "Na, hangkan dayn ha sabab yan biyaktul sin Almasi in paljanjian ba'gu sin Tuhan pa manga mānusiya', ha supaya in manga tau napī' sin Tuhan magad kaniya, makatayma' sin manga karayawan kiyajanji' sin Tuhan kanila, amu in tumatas sampay salama-lama. In karayawan ini, tantu matayma' nila, sabab miyatay in Almasi, ha supaya mapuas in manga mānusiya' dayn ha manga dusa iban hinang nila mangī', amu in nahinang nila ha salugay nila miyamagad sin sara' sin paljanjian nakauna.",
        16: "Na, bang sawpama awn tau maghinang sulat sin pusaka' niya ha hambuuk tau, minsan niya kiyabutang na ha sulat in pagpusaka' niya bang siya buhi' pa, in pusaka' di' pa makawa' sin tau kiyapusakaan niya.",
        17: "In sulat sin pagpusaka' wayruun pa lagi niya ha salugay buhi' pa in nagpusaka'. Subay na mapatay in nagpusaka' ampa makawa' in pusaka' sin tau kiyapusakaan.",
        18: "Na, damikkiyan biya' da isab ha yan in hantang sin sara' daakan sin paljanjian nakauna. Di' mapapanaw in maksud sin paljanjian nakauna bang wayruun dugu' maasag iyungsud pagkulbanan.",
        19: "Hangkan in hīnang hi Musa muna-muna piyasampay niya in katān daakan sin Tuhan pa manga mānusiya', amu in ha lawm sin paljanjian nakauna. Pag'ubus ampa niya kiyawa' in dugu' sin anak sapi' iban kambing liyamugay iban tubig. Na, ampa na isab siya kimawa' batang sin jambangan pagtawagun “hissup”, iban bulbul bili-bili iyaanjibi pula, hīnang pangliligsik dugu', ampa niya liyu'gum pa dugu'. Pag'ubus ampa niya pīgsikan dugu' in Kitab kiyasusulatan sin daakan sin Tuhan iban sin manga tau katān.",
        20: "Ha sa'bu niya nagpipigsik sin dugu', laung niya, “In dugu' ini amuna in makapahugut sin paljanjian sin Tuhan, amu in kiyabutang ha lawm sara' daakan sin aturan hipapaagad kaniyu sin Tuhan.”",
        21: "Damikkiyan pīgsikan da isab dugu' hi Musa in bāy pagtataatan nila iban sin katān kapanyapan hipaglagi nila ha pagtaat nila.",
        22: "In mattan niya ha lawm sin sara' sin paljanjian nakauna, agun in unu-unu katān masuchi sadja bang kapigsikan na sin dugu'. Na, damikkiyan in manga dusa sin mānusiya', di' maampun bang way dugu' maasag.",
        23: "Na, in lugal pagtataatan hīnang sin mānusiya' iban na sin katān luun niya amu in subay pagsuchihun sin dugu' sin hayup, biya' sapantun sadja patta' sin amu in asal puunan pagtataatan didtu ha surga'. Na, ha antara' in pagtataatan yadtu didtu ha surga', na in hipagsuchi ha manga tau ha supaya sila makasūd pa surga', subay dugu' amu in labi maharga' dayn ha dugu' sin hayup.",
        24: "Karna' bilang imam suluhan sin manga mānusiya' pa Tuhan, in Almasi wala' simūd pa lawm lugal suchi hīnang sin mānusiya', amu in sīngud ha amu in yadtu didtu ha surga'. Sagawa' simūd siya tuud pa surga', lāgi' yadtu siya didtu bihaun ha haddarat sin Tuhan nangangayu' duwaa ha palihālan sin kitaniyu katān.",
        25: "Lāgi' in siya bukun biya' sin Imam Dakula' sin manga Yahudi, amu in tahun-tahun sumūd pa lawm bilik landu' tuud suchi ha bāy pagtataatan nagdarā sin dugu' hayup hipanuchi ha manga tau. Sagawa' in Almasi nagminsan niya da līlla' in dugu'-nyawa niya pa Tuhan hipanuchi ha manga mānusiya' dayn ha manga dusa nila.",
        26: "Karna' bang in kaawnan niya biya' sin imam suluhan sin manga Yahudi, na subay siya magbalik-balik mapatay iban sumandal kasiksaan dī ha dunya dayn ha tagnaan sin kapapanjari sin mānusiya' sampay pa bihaun. Sagawa' bukun bihayan in kaawnan niya. Sabab ha masuuk mayan in kahinapusan sin masa, nagminsan da limahil mari pa dunya in Almasi nagbaran mānusiya', iban limilla' sin dugu'-nyawa niya, ha supaya mapuas in manga mānusiya' dayn ha manga dusa nila.",
        27: "Asal in gantaan sin katān mānusiya' mapatay makaminsan iban pag'ubus nila mapatay, na humarap na sila hukuman sin Tuhan.",
        28: "Damikkiyan in Almasi nakaminsan da isab miyatay, karna' iyungsud niya in baran niya piyagkulbanan pa Tuhan, ha supaya mapuas in manga mānusiya' mabanus dayn ha manga dusa nila. Malayngkan magbalik da siya mari pa dunya, bukun na mamuas sin dusa sin mānusiya', sagawa' magpajukup sin kamakbulan sin kalappasan dīhil niya ha manga mānusiya' timatagad kaniya.",
    },
    10: {
        1: "In manga sara' agama iyaagad sin manga Yahudi ha paljanjian nakauna biya' sadja yan hantang lambung singuran dayn ha pakaradjaan didtu ha surga', amu in manga karayawan dumatung ha susūngun. Bukun pa jukup in aturan yan, sabab minsan tahun-tahun in pag'ungsud sin pagkulbanan pa Tuhan, in manga tau magsambahayang di' da dumayaw iban muntul tuud in i'tikad nila pa Tuhan.",
        2: "Iban bang sawpama in pag'ungsud sin manga tau magtataat pa Tuhan sin pagkulbanan pa Tuhan bat makasuchi tuud kanila dayn ha manga dusa nila, na di' na sila masi na mayan magpikil sin manga dusa nila iban hundungan nila na in hinang pagkulban.",
        3: "Sagawa' masi na mayan sila mag'ungsud tahun-tahun sin pagkulbanan pa Tuhan amu in makapatumtum kanila sin manga dusa nahinang nila.",
        4: "Karna' in dugu' sin sapi' iban kambing, asal tantu di' makasuchi ha manga mānusiya' dayn ha manga dusa nila.",
        5: "Hangkan dayn ha sabab ini ha sūng mayan lumahil mari pa dunya in Almasi, namung siya pa Tuhan sin biya' ha ini. Laung niya, “In ikaw, di' kaw mabaya' sin manga pagkulbanan iban sin manga lalabutan piyanglabut kaymu sin manga mānusiya'. Sagawa' yari aku amu in sangunan mu baran mānusiya'.",
        6: "Lāgi' in paglabut nila kaymu sin hayup siyunug atawa sin kaibanan lalabutan, ha supaya sila masuchi dayn ha dusa nila, wala' da nakasulut kaymu.",
        7: "Hangkan yari aku, ū Tuhan ku, līlla' huminang sin unu-unu kabayaan mu, biya' sin kiyasulat ha lawm Kitab sin pasal ku.” (Na, amu yan in pamung sin Almasi ha Tuhan.)",
        8: "Muna-muna tuud laung sin Almasi ha Tuhan, “Di' kaw mabaya' iban wala' kaw kiyasulutan sin manga pagkulbanan sin manga hayup siyunug iban sin kaibanan lalabutan piyanglabut kaymu ha supaya masuchi in manga mānusiya' dayn ha manga dusa nila.” Piyamung sin Almasi in biya' ha yan minsan in manga pagdihil lalabutan pa Tuhan kiyawajib ha sara' sin paljanjian nakauna.",
        9: "Iban laung pa isab sin Almasi, “Yari aku, ū Tuhan ku, līlla' huminang sin unu-unu kabayaan mu.” Na, hangkan wala' na giyuna sin Tuhan in unu-unu katān lalabutan iban iyungsud pagkulbanan kaniya, karna' in Almasi amuna in gimanti' ha manga yan.",
        10: "Pasal in Almasi amuna in nakarihil kamakbulan ha kabayaan sin Tuhan, karna' iyagad tuud hi Īsa Almasi in katān daakan piyahinang kaniya sin Tuhan. Nagminsan niya da līlla' in dugu'-nyawa niya ha pasalan natu' mānusiya', iban dayn didtu kitaniyu nasuchi dayn ha manga dusa nahinang taniyu.",
        11: "Ha paljanjian nakauna in pagtaat pa Tuhan sin manga imam Yahudi nagsubli sila adlaw-adlaw naghinang sin manga hinang kiyawajib kanila. Lāgi' pagbalik-balikan nila in hinang nila ini. Sagawa' in manga hayup siyumbay' nila piyagkulbanan, wala' da nakapapas tuud sin manga dusa sin mānusiya'.",
        12: "Malayngkan in Almasi nagminsan niya da līlla' in dugu'-nyawa niya, iyungsud biya' hantang piyagkulbanan, ha supaya mapapas in dusa sin manga mānusiya', iban in hinang niya yan di' na kagunahan balikan sabab magkasaumulan in kusug sin nahinang niya yan. Lāgi' bihaun yadtu siya limilingkud ha dapit pa tuu sin Tuhan.",
        13: "Na, bihaun yadtu siya didtu timatagad sin waktu daugun na sin Tuhan in katān simusulang kaniya, iban mahinang sila biya' sapantun paggigiikan sin siki niya.",
        14: "Na, dayn ha sabab nagminsan niya da līlla' in dugu'-nyawa niya, in manga mānusiya' amu in nasuchi niya dayn ha manga dusa nila, itungun na sin Tuhan mabuntul biya' sin wala' nakarusa.",
        15: "Iban in himumūngan ini bunnal, karna' minsan in Rū sin Tuhan, simaksi' sin kasabunnalan niya ini, pasal kiyasulat ha lawm Kitab, amu agi,",
        16: "“‘Na, biya' ha ini,’ laung sin Tuhan, ‘in aturan sin paljanjian panaugun ku mawn kanila ha waktu susūngun. Papahūpun ku in manga sara' ku pa lawm bigi-jantung nila iban hiukkil ku pa lawm pamikil nila.’”",
        17: "Iban kiyabayta' pa isab, amu agi, “Di' ku na tumtumun in manga dusa iban manga hinang mangī' nahinang nila.”",
        18: "Na, ha antara' iyampun na sin Tuhan in manga dusa natu', na in hāti niya, di' na kalagihan mag'asag dugu' magbalik hiungsud pa Tuhan ha supaya masuchi in dusa sin manga mānusiya'.",
        19: "Hangkan bihaun manga taymanghud ku, luhaya na tuud kitaniyu sumuuk pa Tuhan, lāgi' makasūd pa surga', amu in hulaan sin Tuhan, karna' in labayan tudju madtu naukab na, pasal piyaglilla' hi Īsa Almasi in dugu'-nyawa niya ha pasalan sin manga mānusiya'.",
        20: "Pag'ubus mayan piyaglilla' sin Almasi in dugu'-nyawa niya, naukab na in labayan ba'gu pa Tuhan amu in nakarihil kātu'niyu sin kabuhi' sabunnal. Karna' in ginhawa-baran sin Almasi nasagsag biya' sapantun sin kurtina amu in nagirit nagduwa.",
        21: "Na, bihaun, siya na in Imam Dakula' labi makawasa magsuluhan ha manga mānusiya' pa Tuhan. Siya in makapagbaya' ha tau katān agad ha Tuhan.",
        22: "Hangkan subay kitaniyu sumuuk na pa Tuhan iban sin atay natu' tulid iban pahugutun natu' na in pangandul natu' kaniya iban subay kitaniyu di' na magduwa-ruwa, sabab in lawm atay iban pamikil taniyu nasuchi na sin dugu' sin Almasi, iban bakas na kitaniyu nagpaligu' tanda' sin nasuchi na kitaniyu sin Tuhan.",
        23: "Lāgi' subay kitaniyu manghuwat-huwat tuud sin manga janji' sin Tuhan kātu'niyu, karna' di' sin Tuhan balubahun in janji' niya.",
        24: "Subay natu' parulihun in pagkahi natu'. Tabangan natu' sila iban pakitaun natu' lasa, ha supaya isab in sila lumasa ha kaibanan nila iban huminang sin unu-unu in marayaw.",
        25: "Damikkiyan subay natu' di' bugtuun in pagtipun-tipun natu' magtaat pa Tuhan ha supaya kitaniyu di' mahinang biya' sin kaibanan amu in liyawaan na baya' magtipun-tipun iban sin manga pagkahi nila Almasihin. In labi marayaw hinangun natu', subay kitaniyu magtipun magtabang-tiyabangi ha supaya humugut in īman taniyu, karna' masuuk na in pagbalik sin Panghu' natu' Īsa mari pa dunya.",
        26: "Na, bang ubus natu' na kiyaingatan in kasabunnalan sin in hi Īsa miyatay ha supaya kitaniyu masuchi dayn ha manga dusa taniyu, ampa tuurun taniyu maghinang na mayan sin makarusa, na wayruun na huwat-huwatun natu', sabab wayruun na dugaing kulban in taymaun sin Tuhan makapuas sin dusa sin mānusiya'.",
        27: "Amuna sadja in kasūngan natu' magtagad sin adlaw kiyamat, amu in makabuga' tuud, sabab duun ha adlaw yan hipananam sin Tuhan in murka' niya ha manga katān simusulang kaniya. Maubus sila kaunun sin kāyu!",
        28: "Ha masa nakauna yadtu hisiyu-siyu in lumanggal sin sara' amu in piyanaug sin Tuhan dayn kan Musa, ampa awn duwa tū tau sumaksi' sin bunnal tuud limanggal siya sara', na patayun siya. Lāgi' di' pagpakitaun luuy in tau biya' ha ini.",
        29: "Na, bang in tau biya' ha yan piyananam da siksa' sin Tuhan, na amu pa ka in di' masiksa' in tau mutas iban sumulak ha Almasi, amu in Anak Tuhan? Labi in siksa' kaniya karna' wala' niya hiyalgaan in dugu' sin Almasi, amu in nakarihil kamakbulan sin paljanjian ba'gu iban amu in piyanuchi kaniya dayn ha manga dusa niya. Iban dayn ha hinang niya yan, biya' niya da sīpug in Rū sin Tuhan, amu in makasi-maulung kātu'niyu baldusa. Hangkan in tau maghinang biya' ha yan tantu numanam tuud kasiksaan ha adlaw kiyamat.",
        30: "Karna' asal natu' kaingatan dayn ha lawm Kitab sin nagparman in Tuhan, amu agi, “Hipananam ku da in baws sin nahinang nila mangī' iban tungbasan ku da.” Iban siyugpatan pa isab sin Tuhan in Parman niya, amu agi, “Butangan ku da hukuman in katān hinang mangī' sin manga tau ku, amu in simulak sin karayawan dīhil ku kanila.”",
        31: "Na, sangat tuud makabuga' in parasahan sin tau, amu in kabutangan hukuman sin Tuhan, karna' in sumiksa' kaniya bukun sadja bat hambuuk tuhan-tuhan sadja, sagawa' amu in Tuhan buhi' salama-lama!",
        32: "Katumtuman niyu ka in waktu ba'gu pa kamu nakaingat sin hindu' kasabunnalan amu in kiyahagad niyu? Bukun ka kiyasandalan niyu in unu-unu kasigpitan iban wala' da nahagin in īman iban pangandul niyu?",
        33: "Masi-masi in kusug sin īman niyu minsan awn waktu pagsipugun iban pagbinsanaun kamu ha katauran tau, sabab agad kamu ha Almasi. Iban diyapitan niyu in pagkahi niyu Almasihin amu in paghinangun biya' ha ini sin manga tau.",
        34: "Iban piyakita' niyu da isab in luuy niyu ha pagkahi niyu Almasihin amu in najijīl. Iban wala' da isab kamu nasusa minsan kiyawa' in alta' niyu sin manga tau kaibanan. Gām mayan kiyūgan kamu pasal natatantu niyu sin labi pa dayn ha yan in alta' nagtatagad kaniyu ha surga', amu in alta' di' malawa' kasaumulan.",
        35: "Hangkan paisuga in lawm atay niyu, ha supaya niyu matayma' in tungbas marayaw, amu in tungbas dakula' hirihil sin Tuhan kaniyu.",
        36: "Lāgi' subay kamu masabal ha unu-unu katān, ha supaya kamu makahinang sin kabayaan sin Tuhan, iban ha supaya niyu matayma' in kiyajanji' kaniyu sin Tuhan.",
        37: "Karna' kiyabayta' ha lawm Kitab, amu agi, “Bukun na malugay dumatung na in tau piyagtatagad-tagaran niyu, iban di' tuud matarasaw in pagdatung niya.",
        38: "Iban in manga tau ku amu in mabuntul, awn kabuhi' nila kasaumulan, bang sila mangandul tuud kāku'. Sagawa' hisiyu-siyu kanila in mutas dayn kāku', na tantu di' tuud aku kasulutan ha tau yan.”",
        39: "Sagawa' in kitaniyu manga Almasihin bukun biya' ha yan. Di' kitaniyu mutas dayn ha Tuhan pasal in yan makarā kātu' pa kamulahan. Gām mayan pahugutun natu' in pangandul taniyu kaniya, karna' amu yan in makalappas kātu'niyu dayn ha kamulahan ha adlaw mahuli.",
    },
    11: {
        1: "Na, unu ta' in hāti sin pangandul? In hāti sin pangandul ini, natatantu natu' sin maawn ha susūngun in unu-unu hiyuhuwat-huwat natu'. Iban dayn ha pasal sin pagpangandul natu' magsabunnal kitaniyu ha unu-unu na di' natu' kakitaan.",
        2: 'In Tuhan kiyasulutan ha manga tau sin masa nakauna yadtu pasal sin pangandul nila kaniya.',
        3: "Iban dayn ha pasal sin pangandul natu', kaingatan taniyu sin dayn ha Parman sin Tuhan piyapanjari niya in ālam iban na sin katān luun niya. Hangkan in katān kakayaan kakitaan taniyu dī ha dunya, guwa' dayn ha di' natu' kakitaan.",
        4: "Biya' na sin agi ku, in manga tau sin masa nakauna yadtu nagparachaya ha Tuhan. Biya' na kan Hābil, dayn ha pasal sin pangandul niya ha Tuhan, nagsumbay' siya hayup pagkulbanan pa Tuhan labi marayaw dayn sin lalabutan dīhil pa Tuhan sin taymanghud niya hi Kābil. Dayn ha pasal sin pangandul hi Hābil, tiyayma' siya sin Tuhan hambuuk tau mabuntul karna' tiyayma' sin Tuhan in lalabutan dīhil niya. Na, minsan hi Hābil mawgay na miyatay, awn kiyabīn niya kātu'niyu hambuuk pamintangan pasal sin kusug sin pagparachaya niya pa Tuhan.",
        5: "Damikkiyan in hi Idris isab, dayn ha pasal sin kusug sin pangandul niya ha Tuhan, wala' siya nakalabay kamatay. Iyangkat siya sin Tuhan pa lawm surga'. Liyawag siya sin manga tau, sagawa' way siya kiyabaakan sabab naangkat na siya madtu pa Tuhan. Lāgi' kiyasulat isab ha Kitab sin ha waktu dī pa hi Idris ha dunya, kiyasulutan in Tuhan kaniya.",
        6: "In Tuhan di' tuud kasulutan ha hisiyu-siyu na tau bang di' mangandul kaniya. Karna' in tau mangarap pa Tuhan subay tuud siya magparachaya sin awn in Tuhan. Subay siya magparachaya sin tungbasan sin Tuhan pa marayaw in hisiyu-siyu in matuyu' lumawag sin dān tudju mawn kaniya.",
        7: "In hi Nū hambuuk isab tau nangandul ha Tuhan. Dimungug iban nagkahagad siya ha bānda' kaniya sin Tuhan sin awn dumatung musība pa dunya ha susūngun. Hangkan nagkahagad siya iban naghinang siya sin bahitra', amu in adjung dakula' siyakatan niya iban sin anak-asawa niya. Na, in hi Nū, ītung sin Tuhan hambuuk tau mabuntul pasal sin pagpangandul niya ha Tuhan iban in hinang niya amuna in sabab hangkan in kaibanan tau biyutangan hukuman dusa.",
        8: "Damikkiyan in hi Ibrahim hambuuk da isab tau nangandul ha Tuhan. Pasal sin pangandul niya ha Tuhan, nagkahagad siya diyaak sin Tuhan minīg dayn ha hula' niya, ampa siya piyakadtu pa hula' kiyajanji' sin Tuhan kaniya. Na, miyadtu siya minsan niya di' kaingatan bang haunu tungud in hula' kadtuun niya.",
        9: "Iban dayn ha pasal sin pangandul niya ha Tuhan, himula' siya ha hula' kiyajanji' kaniya sin Tuhan, sa' biya' siya hantang hambuuk tau dayn ha dugaing hula' namanaw-panaw sadja. Naglatun-latun siya dayn ha hambuuk lugal pa hambuuk lugal, iban in piyagbāyan niya hīnang dayn ha pais hayup. Lāgi' biya' da isab kaniya in paghula'-hula' sin anak niya hi Isahak iban sin apu' niya hi Ya'kub, amu in nakalamud da isab kiyajanjian sin Tuhan sin hula' ini.",
        10: "Na, siyandalan hi Ibrahim in parasahan sin paghula'-hula' niya, sabab hiyuhuwat-huwat niya in hula' giyaganta' iban piyaawn sin Tuhan didtu ha surga', amu in pag'iyanun dāira kakkal.",
        11: "Damikkiyan in hi Sahara, amu in asawa hi Ibrahim, nangandul da isab ha Tuhan. Hangkan minsan siya di' makaanak iban malaas na tuud, na nakaanak da siya sabab sin pangandul niya ha janji' sin Tuhan kaniya.",
        12: "Iban in hi Ibrahim maas na tuud, amu in pag'iyanun di' na tūpun makabaak anak. (Sagawa' nakabaak da sila anak kay Sahara.) Lāgi' in panubu' hi Ibrahim timaud na biya' sin taud sin bituun namulikit ha langit, iban biya' sin buhangin ha higad daplakan amu in way dapat itungun.",
        13: "In katān tau nasabbut ku yan, wala' tuud nalawa' in pangandul nila ha Tuhan sampay sila miyatay, minsan nila wala' natayma' in kiyajanji' kanila sin Tuhan ha sa'bu nila buhi' pa. Karna' asal nila natatantu sin dumatung da in adlaw magmakbul da in kiyajanji' kanila sin Tuhan. Hangkan ha salugay nila buhi' ītung nila in baran nila biya' namanaw-panaw sadja dī ha dunya.",
        14: "Na, dayn ha pamung sin manga tau yan sin ītung nila in baran nila namanaw-panaw sadja dī ha dunya, na matampal na tuud sin awn hiyuhuwat-huwat nila dugaing hula', amu in hula' luggiya' hulaan nila kasaumulan.",
        15: "Lāgi' in manga tau ini, wala' na nagpikil pasal sin hula' tiyaykuran nila. Karna' bang sila miyaya' nagbalik pa hula' nila tagna' makabalik sadja sila.",
        16: "Sagawa' bukun in hula' yan in kabayaan nila paghulaan. In iyangut nila paghulaan amu in labi tuud marayaw dayn ha hula' nila, amu in hula' pagngānan surga'. Hangkan in Tuhan di' masipug tawagun Tuhan nila pasal kiyasulutan in Tuhan sin kusug sin pangandul nila kaniya. Lāgi' tiyatagamahan sila sin Tuhan hula' marayaw didtu ha surga'.",
        17: "Manjari in hi Ibrahim siyulayan sin Tuhan in kusug sin pangandul niya kaniya. Diyaak niya hi Ibrahim hipapatay in anak niya hi Isahak hinangun pagkulbanan. Na, iyagad hi Ibrahim in daakan sin Tuhan kaniya. Sūng na patayun hi Ibrahim in tunggal anak niya dayn kan Sahara hinangun pagkulbanan, minsan da kiyajanjian siya sin Tuhan sin tumaud in panubu' niya dayn ha anak niya ini.",
        18: "Karna' nakapamung in Tuhan kaniya, amu agi, “Tumaud in panubu' mu dayn ha anak mu hi Isahak. Amu yan in janji' ku kaymu.”",
        19: "Ha pikilan hi Ibrahim minsan niya patayun hi Isahak pagkulbanan pa Tuhan, kagausan da sin Tuhan buhiun magbalik. Na, amu in pagbahasahun biya' da itungan nabuhi' nagbalik dayn ha kamatay hi Isahak pasal bang wala' liyāng sin Tuhan hi Ibrahim, in hi Isahak asal tantu mapatay.",
        20: "Damikkiyan dayn ha sabab sin pangandul hi Isahak ha janji' sin Tuhan, biyaytaan niya in manga anak niya hi Ya'kub kay Isaw sin ha susūngun paratungan da sila karayawan sin Tuhan.",
        21: "Iban biya' da isab ha yan in kusug sin pangandul hi Ya'kub ha janji' sin Tuhan. Karna' hambuuk adlaw ha waktu sin kalaas niya na tuud, sin masuuk na siya matay, gimunggung siya ha tungkud niya, ampa siya simujud pa Tuhan. Piyangayuan niya duwaa pa Tuhan in duwa apu' niya, anak hi Yusup.",
        22: "Damikkiyan in hi Yusup nangandul ha janji' sin Tuhan hangkan ha waktu masuuk na siya mapatay namung siya sin in manga tau bangsa Yahudi makaīg da dayn ha hula' Misir. Lāgi' piyagbīn niya ha manga pagkahi niya bangsa Yahudi hipaparā in bangkay niya bang sila maglayn na dayn ha hula' Misir.",
        23: "Damikkiyan, ha waktu piyag'anak hi Musa, in manga ina'-ama' niya nangandul da isab ha Tuhan. Hangkan pagkita' nila sin mahal-mahal tuud in lingkat niya, tiyapuk nila hi Musa ha lawm tūy bulan dayn ha adlaw sin kapag'anak kaniya. Wala' tuud sila miyuga' simulang sin sara' sin Pir'awn pasal sin kusug sin pangandul nila ha Tuhan.",
        24: "Damikkiyan in hi Musa, natau-maas mayan siya, piyakita' niya da isab in kusug sin pangandul niya ha Tuhan. Hangkan atas niya liyupusan in ngān niya bilang anak sin dayang-dayang, anak sin Pir'awn, (amu in nakapūt iban nakaipat kaniya sin sibi'-sibi' pa siya).",
        25: "Mabaya' pa siya umunung magsandal sin kabinsanaan ha manga pagkahi niya Yahudi, amu in manga tau sin Tuhan, dayn sin magad siya ha manga hinang mangī' sin tau ha hula' Misir. Kaingatan niya sin in paglami-lami iban dayaw parasahan hangkaray' da, di' da tumatas malugay.",
        26: "Lāgi' napikil hi Musa sin marayaw pa siya sumandal sin kahinaan unu-unu na ha pasalan sin Almasi, dayn sin magparūl siya sin katān pangalta' ha hula' Misir. Karna' in mahalga' kaniya in tungbas matabuk niya dayn ha Tuhan.",
        27: "Dayn ha pasal sin kusug sin pangandul hi Musa ha Tuhan minīg siya dayn ha Misir. Wala' tuud siya miyuga' ha Pir'awn iban wayruun pagduwa-ruwa niya pasal sin pag'īg niya dayn ha Misir. Minsan siya limabay kabinsanaan, wala' tuud siya nagbalik pa Misir sabab biya' hantang kīkita' niya in Tuhan miyamagad kaniya.",
        28: "Dayn da isab ha kusug sin pangandul hi Musa ha Tuhan kiyahagad niya in daakan kaniya sin Tuhan. Hangkan (ha way pa sila nakaīg dayn ha hula' Misir), hīnduan niya in manga pagkahi niya Yahudi hipasumbay' in bili-bili. Ubus ampa niya diyaak papigsikan in manga lawang bāy nila sin dugu' sin bili-bili ha supaya di' mapatay in katān anak magulang sin manga Yahudi bang lumabay na in malāikat naraak sin Tuhan kumawa' sin nyawa sin katān anak magulang sin manga tau ha Misir. Amuna ini in tagnaan sin paghinang pagtawagun “Paglappas dayn ha Kamatay.”",
        29: "Damikkiyan dayn ha kusug da isab sin pangandul sin manga tau Israil, nakalabay sila dayn ha gi'tungan sin Lawd Pula pa hansipak hula', sabab tiyahayan in lawd liyabayan nila nabiya' tuud ginlupaan. Sagawa' miyawn mayan in manga tau Misir imapas kanila, nagtaklup nagbalik in dagat sarta' kiyasauban iban naubus sila nalu'mus ha lawm dagat.",
        30: "Iban dayn da isab ha kusug sin pangandul sin manga tau Israil ha Tuhan, nalubu in ād batu sin hula' Ariha, amu in hula' sin manga banta nila. Karna' nagkahagad sila ha daakan sin Tuhan kanila hipapalibut kanila adlaw-adlaw ha lawm hangka-pitu in ād batu sin hula' Ariha. Sakali ha hikapitu sin adlaw nalubu in ād batu biya' da tuud sin kiyabayta' sin Tuhan kanila.",
        31: "Sagawa' ha lawm dāira sin Ariha awn hambuuk babai wala' nakaagad miyatay ha manga tau di' magkahagad ha Tuhan. In ngān sin babai ini hi Rahab, hambuuk babai naghihinang mangī'. Malayngkan minsan siya hambuuk babai mangī' awn pangandul niya ha Tuhan. Hangkan tiyabangan niya in duwa ispay tau Israil, amu in naraak muna pa lawm dāira sin Ariha.",
        32: "Liyu dayn duun ha manga tau nasabbut ku yan, mataud pa tau sin masa nakauna yadtu in nangandul tuud ha Tuhan. Di' ku na matagīd'īd in manga nahinang hinda Gidiyun, Barak, Samsun, Jipta, Daud, Samwil iban na sin manga kanabihan pasal kulang na in waktu ku.",
        33: "Dayn ha sabab sin kusug sin pangandul sin manga tau sin masa nakauna yadtu, in kaibanan kanila imatu nagbunu' ha manga tau dayn ha hula' dakula' iban dimaug sila ha pagbunuan. In kaibanan kanila mabuntul magpapanaw sin sara' ha lawm hula' nila iban natayma' nila in unu-unu karayawan kiyajanji' kanila sin Tuhan. Iban minsan in manga singa', amu in sattuwa talun, di' da makaukab sin simud nila mangutkut ha manga tau makusug in pangandul ha Tuhan.",
        34: "In kaibanan kanila amu in kiyatilu' pa lawm kāyu, wala' naunu. Iban in kaibanan wala' nabunu' sin banta nila. In kaibanan minsan malamma kimusug in pamaranan nila. Lāgi' in kaibanan landu' maisug ha pagbunuan iban pagdaugun nila sadja magbunu' in manga banta nila dayn ha dugaing hula'.",
        35: "Iban awn manga babai dayn ha kusug sin pangandul nila ha Tuhan nabuhi' nagbalik dayn ha kamatay in manga kalasahan nila. In kaibanan ha masa nakauna yadtu, amu in nagkasaggaw iban napinjala' pasal sin pangandul nila ha Tuhan, atas nila nagpapatay dayn sin bugtuun nila in pagpangandul nila ha Tuhan, pasal giyuguun nila sin labi marayaw in parasahan nila ha adlaw mahuli.",
        36: "In kaibanan tau nagpaparachaya ha Tuhan piyagsipug-sipug iban piyaglubakan sin manga tau di' magkahagad ha Tuhan. In kaibanan isab hiyukutan sin kadina ampa liyuun pa lawm jīl.",
        37: "Na, in kaibanan miyatay piyagtilu' sin batu, in kaibanan piyagkatkat nagduwa, iban in kaibanan piyaglagut sin pakukus. (In kaibanan piyagdūy dayn ha manga kabāyan nila.) Hangkan nagkadtu-mari na sadja sila dayn ha hambuuk lugal pa hambuuk lugal iban pagbadju' nila pais bili-bili atawa pais kambing. Lāgi' in sila nagkulang-kabus na ha unu-unu katān. Napinjala' iban nabinsana' tuud sila.",
        38: "Wayruun na tutug hulaan nila. Biya' na sila hantang manga tau paguy naglatun-latun dayn ha hula' paslangan mahunit paghulaan, pa kabūran, pa lawm manga sungab batu iban pa manga lungag ha lawm lupa'. In manga tau biya' ha ini, di' tūpun maghula' ha dunya maglamugay iban sin manga tau jahulaka'.",
        39: "Landu' tuud in kalagguan nakawa' sin manga tau nasabbut ku yan dayn ha pagpangandul nila ha Tuhan. Malayngkan sampay sadja sila miyatay wala' nila natabuk in kiyajanji' sin Tuhan kanila,",
        40: "pasal awn maksud sin Tuhan labi marayaw giyaganta' niya kātu'niyu. In maksud sin Tuhan, patagarun in manga tau sin masa nakauna yadtu ha supaya kitaniyu iban sila magsama-sama katān makatayma' sin kiyajanji' sin Tuhan, amu in janji' makaīg sin katān salla' natu'.",
    },
    12: {
        1: "Na, bihaun in kitaniyu ini biya' hantang nalilibut sin manga tau mataud tuud sin masa nakauna yadtu amu in manga saksi' taniyu. (Dayn ha kusug sin parachaya nila, napakita' nila sin in Tuhan tantu tuud kapangandulan.) Na, hangkan pagga in kitaniyu ini biya' hantang naglumba' nagdagan, na subay natu' īgan dayn ha baran natu' in unu-unu makabu'gat sin pagdagan natu' iban butawanan natu' na in manga hinang mangī' amu in kabiyaksahan natu' paghinangun. Lāgi' subay natu' tuyuan tuud in piyagbahasa pagdagan ini, amu in daakan sin Tuhan kātu'niyu.",
        2: "Iban subay natu' pahambuukun tuud duun kan Īsa in pamikil iban atay taniyu, karna' siya in tuburan iban magpapahugut sin parachaya natu' dayn ha tagnaan sampay pa kahinapusan. Siyandalan niya tuud in katān kasiksaan ha kalansang kaniya pa usuk, lāgi' wala' siya nagparuli sin kasipugan mapatay siya hilansang pa usuk, pasal natatantu niya in kakuyagan matabuk niya tungbas sin hinang niya. Na, bihaun yadtu siya ha surga' limilingkud ha dapit pa tuu sin kursi sin Tuhan.",
        3: "Tumtuma iban pahūpa pa lawm pamikil niyu in parachaya hi Īsa ha Tuhan ha sa'bu niya limalabay kasiksaan ha lawm lima sin manga tau baldusa, amu in simulang kaniya. Na, amu yan in kannala niyu ha supaya isab di' niyu mapikil sin wayruun da kapūsan sin pagparachaya niyu iban bat niyu di' butawanan in pangandul niyu.",
        4: "Na, biya' na sin kiyaiingatan niyu, wayruun pa isab dayn kaniyu in miyatay pasalan sin tiyaggahan niyu in baran niyu huminang sin unu-unu mangī'.",
        5: "Kiyalupahan niyu na ka in pamung sin Tuhan, amu in makarayaw atay sin kamu amu in nīyat niya manga anak niya, karna' kiyasulat ha Kitab in pamung niya, amu agi: “Manga anak ku, pagkahagad kamu bang kamu pantunun ku, iban ayaw niyu butawani in pangandul niyu kāku' bang ta kamu paratungan kabinsanaan.",
        6: "Karna' pantunun ku in katān tau kalasahan ku, iban paratungan ku kabinsanaan in katān tau amu in taymaun ku hinangun anak.”",
        7: "Na, hangkan unu-unu na in kabinsanaan dumatung kaniyu sandali niyu tuud, pasal in kabinsanaan yan amuna in hipamantun sin Tuhan kaniyu, sabab in kamu nīyat niya manga anak niya. Karna' awn ka anak in di' pagpantunun sin ama' niya?",
        8: "Iban bang kamu di' pagdatungan kabinsanaan biya' sin katān anak niya, in hāti niya bukun kamu anak niya tuud.",
        9: "Lāgi' minsan isab in ama' taniyu dī ha dunya pagpantunun nila da kitaniyu, sagawa' masi natu' sila piyag'aaddatan. Na, amu pa in di' natu' kahagarun in Ama' natu' amu in nagpaawn sin nyawa sin mānusiya'. Karna' abila kitaniyu umungsud sin baran taniyu pa Tuhan karihilan niya kitaniyu sin kabuhi' salama-lama.",
        10: "Iban in pagpantun kātu'niyu sin manga ama' natu' dī ha dunya bukun da isab malugay. In pagpantun nila agad sadja ha unu-unu napikil nila marayaw. Sagawa' in Tuhan pantunun niya tuud kitaniyu ha supaya kitaniyu mabiya' sin kaawnan niya, amu in suchi tuud dayn ha unu-unu kangīan.",
        11: "Ha bihaun bang kitaniyu pantunun sin Tuhan, di' kitaniyu kūgan sabab sin sakit sin kabinsanaan kananaman natu'. Sagawa' bang kitaniyu magkahagad iban sumandal sin pagpantun sin Tuhan, na dumayaw in laku-tabiat natu' iban sumannyang in lawm pamikil natu'. Amu yan in tungbas marayaw makawa' natu'.",
        12: 'Na, hangkan pahuguta in parachaya niyu iban pakusuga in pangandul niyu pa Tuhan.',
        13: "Lāgi' subay niyu di' bugtuun in panawan niyu dayn ha dān mabuntul ha supaya in manga kaibanan pagkahi niyu, amu in bukun pa mahugut in parachaya nila kan Īsa, katabangan niyu ha di' humuka' in parachaya nila, sagawa' gām mayan dumayaw in pag'agad nila ha Almasi.",
        14: "Damikkiyan hallii niyu tuud in di' kamu makapagkawkālu iban sin manga tau minsan hisiyu, iban tuyu' tuud kamu huminang sin unu-unu marayaw amu in makasuchi kaniyu, karna' hisiyu-siyu in tau bukun suchi di' makapagkita' iban Tuhan ha adlaw mahuli.",
        15: "Lāgi' ayad kamu ha supaya wayruun dayn kaniyu in mamutawan iban sumulak sin kasi-lasa iban tulung-tabang sin Tuhan. Halli' da kamu ha supaya wayruun dayn kaniyu in biya' ha yan, sabab bang awn, na bukun malugay mataud in malamin sin addat niya mangī'.",
        16: "Damikkiyan ayad kamu ha supaya wayruun dayn kaniyu in maghinang sin hinang maasihat, atawa mabiya' kan Isaw, amu in way buga' ha Tuhan. Karna' in hi Isaw, pagga siya in anak magulang, siya in kiyabugsuan sin janji' sin Tuhan. Sagawa' in kapatutan niya bilang anak magulang, amu makatayma' sin janji' sin Tuhan, piyagsambi' niya iban sin hangka-pinggan kakaun.",
        17: "Na, sakali kaingatan niyu da isab, pag'ubus yadtu napikil da hi Isaw sin marayaw bang siya kapangayuan duwaa sin ama' niya ha supaya siya dihilan da isab karayawan sin Tuhan. Sagawa' wala' naagad in kabayaan niya, sabab way na dapat niya maminda sin bakas nahinang niya. Minsan siya nagsusun nagtangis, di' niya na makawa' magbalik in kapatutan niya tumayma' sin janji' sin Tuhan.",
        18: "Iban bihaun ha ba'gu aturan sin pagtaat pa Tuhan wayruun kamu nakananam biya' sin kiyalabayan sin manga Yahudi sin masa nakauna yadtu. Karna' ha waktu duun sila ha Būd Turusina, (amu in waktu kapanaug sin Tuhan sin Parman niya mawn kan Musa) landu' tuud miyuga' in manga Yahudi pasal nākita' sila kāyu nalalaga, iban nanigidlum sarta' naghangin makusug.",
        19: "Iban diyungug nila da isab in katingug makusug tuud biya' sin katingug sin tambuli' iban tingug sin suwara makabuga'. Pagdungug nila sin suwara yadtu, nangayu' sila suhud pa Tuhan bang mān di' patumlangun sin Tuhan in pagparman niya mawn kanila, sabab landu' tuud sila miyuga'.",
        20: "Hangkan sila landu' tuud miyuga', pasal biya' ha ini in Parman sin Tuhan, amu agi, “Ayaw kamu magsuuk mari pa būd ini, karna' hisiyu-siyu in sumuuk mari minsan da sattuwa subay batuhun bat siya mapatay.”",
        21: "Iban minsan in hi Musa landu' da miyuga' pagkita' niya sin biya' hādtu, karna' nakapamung siya, laung niya, “Namidpid aku yan sin buga'.”",
        22: "Sagawa' bihaun in pagtaat niyu pa Tuhan bukun biya' sin manga tau nakauna yadtu. Karna' ha katayma' niyu sin paljanjian ba'gu, in kamu ītung na sin Tuhan matūp humula' ha Bud Siyun ha surga' amu in hulaan sin Tuhan di' magkamatay iban sin ibuhan malāikat.",
        23: "Na, bang paamuhun in kamu yan kiyalamud na ha manga pag'iyanun anak magulang sin Tuhan amu in ngān nila kiyasulat na didtu ha surga'. Nakalamud na kamu ha pagtipun-tipun iban pagkūg-kuyag nila. Lāgi' biya' da kamu yan nakasūd pa haddarat sin Tuhan, amu in manghuhukum ha mānusiya' katān, iban biya' da kamu nakapaghambuuk iban sin manga tau mabuntul, amu in miyatay na iban suchi na tuud dayn ha unu-unu katān mangī'.",
        24: "Lāgi' in kamu yan awn na kasugsug kan Īsa, amu in suluhan sin manga nagdusa pa Tuhan. In aturan sin paljanjian ba'gu naawn sabab naasag in dugu' hi Īsa piyanuchi sin lawm atay sin katān tau timayma' kaniya ha supaya sila maampun sin Tuhan. In dugu' hi Īsa naasag labi awla tuud marayaw dayn sin dugu' hi Hābil (naasag ha kabunu' kaniya), pasal in dugu' hi Īsa naasag ha supaya in tau katān makabaak kaampunan dayn ha Tuhan, sagawa' in dugu' hi Hābil naasag nangayu' kapamawlihan.",
        25: "Na, pagga biya' ha yan in karayawan sin paljanjian ba'gu dīhil kātu'niyu sin Tuhan, subay tuud kitaniyu dumungug sin Parman niya iban di' sumulang kaniya. Karna' in manga tau sin masa nakauna yadtu, amu in wala' nagkahagad kan Musa amu in nagpahāti sin Parman kanila dī ha dunya, nimanam sila kabinsanaan dayn ha Tuhan. Na, amu pa ka in di' numanam kabinsanaan in kitaniyu, bang taniyu di' dungugun in Tuhan amu in nagparman dayn ha surga'?",
        26: "Sin masa nakauna yadtu, nagparman mayan in Tuhan, najugjug in dunya kaagi sin suwara niya. Sagawa' bihaun nakajanji' in Tuhan, amu agi, “Jugjugun ku magbalik bukun sadja in dunya, sagawa' sampay in unu-unu katān ha liyukupan sin ālam.”",
        27: "Na, biya' ha ini in maana sin bichara yan. In unu-unu katān piyapanjari amu in kumangī' ha waktu sin pagjugjug yan, na malawa' na, ampa in di' kumangī' amuna in makabīn.",
        28: "Hangkan subay kitaniyu magsarang-sukul pa Tuhan pasal pahulaun niya kitaniyu duun ha lawm hulaan niya, amu in hulaan kumakkal saumul-umul di' magkahagin. Subay kitaniyu magtaat kaniya ha aturan makasulut kaniya iban pagsarang-sukul kaniya. Iban subay kitaniyu mag'addat iban magmabuga' kaniya,",
        29: "sabab bang magmurka' in Tuhan taniyu biya' yan sin kāyu makasunug ha unu-unu katān.",
    },
    13: {
        1: "Na, in kitaniyu magtawtaymanghud Almasihin subay natu' di' bugtuun in paglasa-liyasahi natu'.",
        2: "Tumtuma niyu, subay kamu umasip iban sumawmbibi ha manga tau manghanti'-hanti' mawn pa bāy niyu. Karna' ha masa nakauna yadtu awn manga tau nakapangasip iban nakasawmbibi ha manga malāikat nagbaran mānusiya', sagawa' wala' nila kiyaingatan sin namanaw-panaw mawn pa bāy nila in manga malāikat.",
        3: "Ayaw kamu malupa dumihil tabang ha manga najijīl. Pikila niyu biya' da kamu sin didtu imuunung kanila. Damikkiyan tabanga niyu da isab in manga tau ha lawm kabinsanaan. Pikila niyu biya' da kamu imuunung kanila ha lawm kabinsanaan.",
        4: "Damikkiyan, in pagtiyaun sin usug iban babai subay tuud hargaan sin katān, iban subay di' hinangun biya' hambuuk sadja panayam-nayaman. Lāgi' in manga tau tagapaghula' na, subay di' magjina. Pasal butangan sin Tuhan hukuman in manga tau naghihinang maasihat iban magjijina.",
        5: "Iban subay da isab kamu di' maghawa-napsu ha pilak. Subay kamu mamarahi sin unu-unu na in awn kaniyu, karna' tabangun da kamu sin Tuhan. Sabab nakapamung in Tuhan, laung niya, “Di' ta kamu hibīn iban di' ta kamu pasāran kasaumulan.”",
        6: "Na, pagga bihādtu in bichara sin Tuhan subay kitaniyu tumawakkal imiyan, “Tuhan in timatabang kāku'. Di' aku mabuga' minsan unu in hinangun sin tau kāku'.”",
        7: "Iban tumtuma niyu da isab in manga guru niyu bakas, amu in nanghindu' kaniyu sin Parman sin Tuhan. Tumtuma niyu in dayaw sin addat nila dayn ha salugay nila buhi' sampay sila miyatay, ampa niyu singuri in kusug sin pangandul nila ha Almasi.",
        8: "Asal dayn ha waktu tagna' sampay pa bihaun in hi Īsa Almasi di' magkapinda. Di' tuud siya magkapinda sampay pa kasaumulan.",
        9: "Ayaw tuud kamu makawa' sasat sin manga panghindu' ginis-ginisan amu in dugaing dayn sin panghindu' sin Almasi, pasal in manga panghindu' yan makarā kaniyu simiha' dayn ha dān mabuntul. In pangandul niyu ha tulung-tabang sin Tuhan amuna in hambuuk-buuk makapakusug sin īman niyu. Hangkan ayaw kamu magkahagad sin manga panghindu' amu in manglāng kaniyu kumaun sin manga kakaun hiyaram sin sara' agama nila. In manga tau miyagad sin manga sara' sin panghindu' yan, wala' da natabang sin manga sara' yan.",
        10: "In manga tau masi miyamagad sin paljanjian nakauna sin agama Yahudi, way kapatutan nila sumāw sin karayawan makawa' natu' dayn ha kamatay sin Almasi amu in nahinang kulban limappas sin manga dusa taniyu.",
        11: "Ha lawm sara' sin paljanjian nakauna, nawajib ha imam dakula' Yahudi in dumā dugu' sin hayup siyumbay' pa lawm bilik pagngānan lugal landu' tuud suchi. Ubus ampa niya hitukbal lalabutan pa Tuhan ha supaya mapapas in dusa sin manga tau. Sumagawa' in bangkay sin hayup didtu nila sunugun ha guwa' sin kampu piyaghuhulaan nila.",
        12: "Damikkiyan in Almasi miyatay da isab ha guwa' sin dāira ha supaya masuchi sin luggiya' dugu' niya in manga tau suku' niya dayn ha manga dusa nila.",
        13: "Na, hangkan subay kitaniyu gumuwa' dayn ha kampu sin manga Yahudi. (In hāti niya subay kitaniyu di' na magad sin sara' sin agama nila) sagawa' subay Almasi na in agaran taniyu. Lāgi' subay natu' sandalan in unu-unu kahinaan dumatung kātu'niyu pasal sin pag'agad natu' kaniya.",
        14: "Karna' in dunya ini panghapit-hapitan natu' sadja. Bukun ini in hulaan natu' kasaumulan. In hiyuhuwat-huwat natu' hulaan amu in hula' datungan natu' didtu ha surga'.",
        15: "Na, hangkan dayn ha sabab sin karayawan dīhil kātu'niyu sin Almasi subay way pagbugtu' in pagpudji natu' pa Tuhan iban subay natu' hisuwara in pagsarang-sukul natu' kaniya. Lāgi' subay natu' hisuwara in pagsabunnal natu' sin in hi Īsa amuna in Panghu' natu'! Na, in manga lapal-kabtangan niyu yan amuna in biya' hantang lalabutan niyu pa Tuhan.",
        16: "Lāgi' ayaw tuud kamu malupa huminang sin marayaw iban tumabang ha manga tau kiyasisigpitan pasal in manga hinang biya' ha yan amuna tuud in biya' hantang lalabutan makasulut ha Tuhan.",
        17: "Iban subay niyu kahagarun iban hinangun in panghindu' kaniyu sin manga nakura' niyu. Karna' sila na yan in di' magbati'-laul jumaga kaniyu (ha supaya kamu di' sumiha' dayn ha dān tudju pa Tuhan). Iban hangkan bihādtu sabab dumatung da isab in waktu in sila yan mamayhu' pa Tuhan mamayta' bang biya' diin in paghindu' nila kaniyu. Na, bang kamu magkahagad sin panghindu' nila, makuyag tuud sila huminang sin hikatabang nila kaniyu. Sagawa' bang kamu di' magkahagad, na masusa sila iban di' sila makahinang sin hikatabang kaniyu.",
        18: "Damikkiyan ayaw niyu bugtua in pagpangayu' niyu duwaa kāmu' pa Tuhan. Karna' in kami ini wayruun tuud katitipuhan sin lawm pamikil namu' sabab amu sadja in pīpikil namu' in maghinang sin mabuntul.",
        19: "Lāgi' junjungun ku kaniyu bang mayan pangayuun niyu tuud duwaa pa Tuhan sin makabalik aku mawn kaniyu ha masamut ini.",
        20: "Na, manjari in Panghu' natu' Īsa biyuhi' sin Tuhan nagbalik dayn ha kamatay. Ha bihaun biya' siya sapantun hambuuk mag'iipat bili-bili, amu in mag'upiksa' tuud kātu'niyu, amu in biya' sapantun manga bili-bili niya. Karna' dayn ha sabab sin dugu' niya naasag ha kalansang kaniya pa usuk, napaawn in aturan sin paljanjian ba'gu, amu in di' na mapinda kasaumulan. Mura-murahan bang mayan sin Tuhan, amu in tuburan iban mangdirihil sin kasannyangan iban kasulutan, panyapun kamu sin unu-unu na mayan kalagihan niyu, amu in makatabang kaniyu huminang sin kabayaan iban daakan niya kaniyu. Lāgi' bang mayan dayn ha sabab hi Īsa Almasi amu in nanglappas kātu'niyu, tabangan kitaniyu sin Tuhan huminang sin unu-unu katān amu in makasulut kaniya. Mahuli dayn duun, bang mayan in Almasi dihilan kalagguan kasaumulan. Amin.",
        21: "Na, manjari in Panghu' natu' Īsa biyuhi' sin Tuhan nagbalik dayn ha kamatay. Ha bihaun biya' siya sapantun hambuuk mag'iipat bili-bili, amu in mag'upiksa' tuud kātu'niyu, amu in biya' sapantun manga bili-bili niya. Karna' dayn ha sabab sin dugu' niya naasag ha kalansang kaniya pa usuk, napaawn in aturan sin paljanjian ba'gu, amu in di' na mapinda kasaumulan. Mura-murahan bang mayan sin Tuhan, amu in tuburan iban mangdirihil sin kasannyangan iban kasulutan, panyapun kamu sin unu-unu na mayan kalagihan niyu, amu in makatabang kaniyu huminang sin kabayaan iban daakan niya kaniyu. Lāgi' bang mayan dayn ha sabab hi Īsa Almasi amu in nanglappas kātu'niyu, tabangan kitaniyu sin Tuhan huminang sin unu-unu katān amu in makasulut kaniya. Mahuli dayn duun, bang mayan in Almasi dihilan kalagguan kasaumulan. Amin.",
        22: "Na, junjungun ku kaniyu manga taymanghud ku, taynghug tuud kamu iban pahūpa niyu pa lawm pamikil niyu in panghindu' ku kaniyu ha lawm sulat ini, karna' bukun da isab mahaba' in sulat ku ini.",
        23: "Iban yari isab aku magpahāti kaniyu sin pasal sin taymanghud natu' hi Timuti, na, nakaguwa' na dayn ha lawm kalabusu. Na, bang siya makakari da ha masamut, paagarun ku siya mamisita matun kaniyu.",
        24: "Na, mahuli dayn duun mamaid na aku kaniyu sarta' pasampayan niyu in salam-duwaa ku pa manga tau maas duun ha langgal niyu iban na sin katān tau agad ha Tuhan. Iban isab in manga taymanghud niyu dī ha hula' Italiya, yari isab magpasampay sin salam-duwaa nila mawn kaniyu.",
        25: 'Mura-murahan bang mayan in kamu katān dihilan sin Tuhan sin tulung-tabang niya. Wassalam.',
    },
}
